/*
 * MUNIVERSE 데모 데이터 넣기 · 지우기 (브라우저 콘솔용) — node scripts/build-demo-seed.js 로 만든 파일입니다. 직접 고치지 마세요.
 *
 * 넣는 것
 *   - HubContents : Skill 9개 (SKILL.md 첨부), HTML 9개 (실제로 동작하는 HTML 첨부) (리뷰 · 별점 없음)
 *   - AgentList   : 예시 Agent 6개 (행 키가 DEMO-AG- 로 시작, Owner = 실행한 사람, 관련 Skill 연결)
 *   제목은 '[테스트]' 없이 깨끗하게 넣습니다. 같은 제목이 이미 있으면 건너뛰어 두 번 실행해도 중복이 안 생겨요.
 *
 * 쓰는 법
 *   1. Hub 사이트를 열고 F12 → Console 에 이 파일 전체를 붙여 넣고 Enter.
 *   2. 지울 때는 Console 에 hubDemoCleanup() 입력 → 이 스크립트가 넣은 제목 · 행 키의 항목만 휴지통으로 보냅니다.
 */
(function runtime(DATA) {
  (async () => {
    const web = _spPageContextInfo.webAbsoluteUrl;
    const me = _spPageContextInfo.userId;
    const J = { Accept: 'application/json;odata=verbose' };
    const digest = async () => (await (await fetch(web + '/_api/contextinfo', { method: 'POST', headers: J })).json()).d.GetContextWebInformation.FormDigestValue;
    let D = await digest();
    const L = t => `${web}/_api/web/lists/getbytitle('${encodeURIComponent(t)}')`;
    const get = async url => { const r = await fetch(url, { headers: J }); if (!r.ok) { throw new Error(`${r.status} ${url.replace(web, '')}`); } return (await r.json()).d; };
    const post = async (url, body, extra) => {
      const r = await fetch(url, { method: 'POST', headers: { ...J, 'Content-Type': 'application/json;odata=verbose', 'X-RequestDigest': D, ...(extra || {}) }, body: body === undefined ? undefined : JSON.stringify(body) });
      if (!r.ok) { throw new Error(`${r.status} ${url.replace(web, '')}\n${(await r.text()).slice(0, 300)}`); }
      const t = await r.text();
      return t ? JSON.parse(t).d : undefined;
    };
    const multi = a => ({ results: a });
    const day = n => new Date(Date.now() - n * 86400000).toISOString();
    const rel = list => JSON.stringify(list.map(([v, n, d]) => ({ v, d: day(d).slice(0, 10), n })));
    const log = [];
    const step = async (what, fn) => { try { const r = await fn(); log.push({ 단계: what, 결과: '✅' + (typeof r === 'string' ? ' ' + r : '') }); return r; } catch (e) { log.push({ 단계: what, 결과: '❌ ' + e.message.split('\n')[0] }); console.warn(what, e.message); return undefined; } };

    /* 이미 넣은 데모 항목이 있으면 건너뜁니다 (두 번 실행해도 중복이 안 생기게) */
    const C = (await get(`${L('HubContents')}?$select=ListItemEntityTypeFullName,Id`));
    const existing = (await get(`${L('HubContents')}/items?$select=Id,Title,Kind&$top=5000`)).results;
    const has = (kind, title) => existing.filter(r => r.Kind === kind && r.Title === title)[0];
    const contentIds = {};
    const attach = async (id, name, text) => {
      const r = await fetch(`${L('HubContents')}/items(${id})/AttachmentFiles/add(FileName='${encodeURIComponent(name)}')`, { method: 'POST', headers: { ...J, 'X-RequestDigest': D }, body: new Blob([text], { type: 'text/plain;charset=utf-8' }) });
      if (!r.ok) { throw new Error(`첨부 실패 ${r.status}: ${(await r.text()).slice(0, 200)}`); }
    };
    const comment = (id, text) => post(`${L('HubContents')}/items(${id})/Comments`, { text }, { 'Content-Type': 'application/json;odata=nometadata', Accept: 'application/json;odata=nometadata' });
    const rate = (id, v) => post(`${web}/_api/Microsoft.Office.Server.ReputationModel.Reputation.SetRating(listID=@a1,itemID=@a2,rating=@a3)?@a1='{${C.Id}}'&@a2='${id}'&@a3=${v}`);

    const putContent = async (kind, x) => {
      const old = has(kind, x.Title);
      if (old) { contentIds[x.Title] = old.Id; return '이미 있어 건너뜀'; }
      const { file, text, rel: r, stars, review, ...f } = x;
      const it = await post(`${L('HubContents')}/items`, { __metadata: { type: C.ListItemEntityTypeFullName }, ...f, Kind: kind, WorkArea: multi(f.WorkArea), Tools: multi(f.Tools), Scope: multi(f.Scope), Releases: rel(r), Hidden: false });
      contentIds[x.Title] = it.Id;
      await attach(it.Id, `${Date.now()}_${file}`, text);
      // 리뷰 · 별점은 지금은 넣지 않습니다. 넣으려면 WITH_REVIEWS 를 true 로 바꾸세요.
      if (DATA.withReviews && stars) { await rate(it.Id, stars).catch(() => undefined); }
      if (DATA.withReviews && review) { await comment(it.Id, `[★${stars}] ${review}`); }
      return `ID ${it.Id}`;
    };
    for (const s of DATA.skills) { await step(`Skill · ${s.Title}`, () => putContent('Skill', s)); }
    for (const h of DATA.htmls) { await step(`HTML · ${h.Title}`, () => putContent('HTML', h)); }

    /* ---------- AgentList ---------- */
    const lists = (await get(`${web}/_api/web/lists?$filter=Hidden eq false and BaseTemplate eq 100&$select=Id,Title,RootFolder/ServerRelativeUrl&$expand=RootFolder`)).results;
    const norm = s => String(s || '').toLowerCase().replace(/[\s_-]/g, '');
    const hit = lists.filter(l => norm(l.Title) === 'agentlist' || /\/lists\/agentlist$/i.test(l.RootFolder.ServerRelativeUrl))[0];
    if (!hit) { log.push({ 단계: 'AgentList', 결과: '❌ 목록을 찾지 못했어요' }); } else {
      const base = `${web}/_api/web/lists(guid'${hit.Id}')`;
      const info = await get(`${base}?$select=ListItemEntityTypeFullName`);
      const choiceCache = {};
      const choicesOf = async name => {
        if (!(name in choiceCache)) { choiceCache[name] = await get(`${base}/fields/getbyinternalnameortitle('${name}')?$select=Choices,TypeAsString`).then(f => ({ type: f.TypeAsString, list: (f.Choices && f.Choices.results) || [] })).catch(() => null); }
        return choiceCache[name];
      };
      const opsList = ((await choicesOf('OpsStatus')) || { list: [] }).list;
      const ops = ['정식 운영', '운영 중', '안정화 중'].filter(x => opsList.indexOf(x) >= 0)[0] || opsList.filter(x => !/중단|폐기/.test(x))[0];
      const agentRows = (await get(`${base}/items?$select=Id,Title&$top=5000&$filter=startswith(Title,'DEMO-AG-')`)).results;
      for (const a of DATA.agents) {
        await step(`Agent · ${a.AgentName}`, async () => {
          if (agentRows.some(r => r.Title === a.Title)) { return '이미 있어 건너뜀'; }
          const { rel: r, skills, Config, Does, Prompts, ...rest } = a;
          const fields = { __metadata: { type: info.ListItemEntityTypeFullName }, Title: rest.Title, AgentName: rest.AgentName, Summary: rest.Summary, OutputNote: rest.OutputNote,
            Does: Does.join('\n'), Prompts: Prompts.join('\n'), MakerNote: rest.MakerNote, Instructions: rest.Instructions, Config: JSON.stringify(Config),
            Version: r[r.length - 1][0], Releases: rel(r), FirstDeployedOn: day(r[0][2]), DeployedAt: day(r[r.length - 1][2]), OwnerId: me,
            OpenUrl: { __metadata: { type: 'SP.FieldUrlValue' }, Url: 'https://m365.cloud.microsoft/chat', Description: 'Copilot에서 열기' } };
          const skipped = [];
          for (const k of ['BuildTool', 'TaskArea', 'Output', 'Scope', 'Env', 'OpsStatus']) {
            const want = k === 'Env' ? ['Prod'] : k === 'OpsStatus' ? [ops] : [].concat(rest[k]);
            const c = await choicesOf(k);
            if (!c) { skipped.push(k); continue; }
            const ok = want.filter(x => c.list.indexOf(x) >= 0);
            if (!ok.length) { skipped.push(k); continue; }
            fields[k] = c.type === 'MultiChoice' ? { __metadata: { type: 'Collection(Edm.String)' }, results: ok } : ok[0];
          }
          const it = await post(`${base}/items`, fields);
          let note = `ID ${it.Id}` + (skipped.length ? ` (못 넣은 열: ${skipped.join(', ')})` : '');
          const ids = skills.map(t => contentIds[t]).filter(Boolean);
          if (ids.length) {
            await post(`${base}/items(${it.Id})`, { __metadata: { type: info.ListItemEntityTypeFullName }, SkillsId: multi(ids) }, { 'X-HTTP-Method': 'MERGE', 'IF-MATCH': '*' })
              .then(() => { note += ` · Skill ${ids.length}개 연결`; }, () => { note += ' · Skill 연결 열 없음'; });
          }
          return note;
        });
      }
    }

    console.table(log);
    console.log(log.every(x => x.결과.startsWith('✅')) ? '✅ 데모 데이터를 다 넣었어요. Hub를 새로 고쳐 보세요.' : '⚠️ 일부가 실패했어요. 위 표의 ❌ 줄을 보내 주세요.');
    console.log('지울 때는 hubDemoCleanup() 을 입력하세요. 이 스크립트가 넣은 제목의 항목만 휴지통으로 보내요.');
  })().catch(e => console.error('중간에 멈췄어요:', e.message));

  window.hubDemoCleanup = async () => {
    const web = _spPageContextInfo.webAbsoluteUrl;
    const J = { Accept: 'application/json;odata=verbose' };
    const D = (await (await fetch(web + '/_api/contextinfo', { method: 'POST', headers: J })).json()).d.GetContextWebInformation.FormDigestValue;
    const del = url => fetch(url + '/recycle()', { method: 'POST', headers: { ...J, 'X-RequestDigest': D } });
    const titles = { Skill: DATA.skills.map(x => x.Title), HTML: DATA.htmls.map(x => x.Title) };
    const L = `${web}/_api/web/lists/getbytitle('HubContents')`;
    const rows = (await (await fetch(`${L}/items?$select=Id,Title,Kind&$top=5000`, { headers: J })).json()).d.results.filter(r => (titles[r.Kind] || []).indexOf(r.Title) >= 0);
    for (const r of rows) { await del(`${L}/items(${r.Id})`); }
    console.log(`HubContents: ${rows.length}개 휴지통으로`);
    const lists = (await (await fetch(`${web}/_api/web/lists?$filter=Hidden eq false and BaseTemplate eq 100&$select=Id,Title,RootFolder/ServerRelativeUrl&$expand=RootFolder`, { headers: J })).json()).d.results;
    const hit = lists.filter(l => l.Title.toLowerCase().replace(/[\s_-]/g, '') === 'agentlist' || /\/lists\/agentlist$/i.test(l.RootFolder.ServerRelativeUrl))[0];
    if (hit) {
      const B = `${web}/_api/web/lists(guid'${hit.Id}')`;
      const keys = DATA.agents.map(a => a.Title);
      const ar = (await (await fetch(`${B}/items?$select=Id,Title&$top=5000&$filter=startswith(Title,'DEMO-AG-')`, { headers: J })).json()).d.results.filter(r => keys.indexOf(r.Title) >= 0);
      for (const r of ar) { await del(`${B}/items(${r.Id})`); }
      console.log(`AgentList: ${ar.length}개 휴지통으로`);
    }
  };
})({"withReviews":false,"skills":[{"file":"copilot-scenario-assessment.md","Title":"Copilot 활용 시나리오 평가","Summary":"업무 목록만 주면 Copilot 시나리오와 우선순위 점수표를 만들어요","Category":"업무 절차","WorkArea":["제안과 전략 세우기"],"Tools":["Copilot","Cowork","Copilot Studio"],"Scope":["고객 프로젝트용"],"Does":"고객 부서의 업무 목록을 받아 Copilot을 어디에 먼저 쓸지 정해야 할 때\n효과 · 난이도 · 데이터 준비도로 점수를 매겨 Quick Win을 골라야 할 때","Usage":"Copilot 대화에 파일을 첨부하고 \"이 업무 목록으로 시나리오 평가해줘\"라고 말해요. Copilot Studio에서는 Skill로 추가해요.","rel":[["1.0","처음 공유",41],["1.1","총점 공식에 효과 가중치(×2) 추가",18],["1.2","예시 프롬프트 열 추가",4]],"stars":5,"review":"고객 워크숍 끝나고 바로 돌렸더니 Quick Win 3개가 표로 나왔어요. 제안서에 그대로 넣었습니다","text":"---\nname: copilot-scenario-assessment\ndescription: 부서·직무의 업무 목록을 받아 Microsoft 365 Copilot 활용 시나리오를 만들고, 효과·난이도·데이터 준비도로 점수를 매겨 우선순위를 정할 때 사용합니다. \"Copilot 쓸 만한 업무 찾아줘\", \"시나리오 우선순위\", \"Quick Win 골라줘\" 같은 요청에 씁니다.\n---\n\n# Copilot 활용 시나리오 평가\n\n당신은 Microsoft 365 Copilot 도입 컨설턴트입니다. 사용자가 준 부서·직무 정보와 업무 목록만 근거로 시나리오를 만들고 평가합니다. 같은 입력을 넣으면 누가 돌려도 같은 점수가 나오도록, 아래 기준표를 그대로 적용합니다. 추측한 값은 반드시 \"가정\"이라고 표시합니다.\n\n## 입력으로 받는 것\n- 부서 / 직무 / 인원\n- 반복 업무 목록: 업무명, 빈도(주 몇 회), 1회 소요 시간(분)\n- 쓰는 앱 (Outlook, Teams, Word, Excel, PowerPoint, SharePoint, OneDrive, 사내 시스템 등)\n- 업무에 쓰는 자료가 어디에 있는지 (SharePoint · Teams · OneDrive · 메일 · 개인 PC · 사내 시스템)\n\n빠진 정보가 있으면 표를 만들기 전에 **최대 3개까지만** 물어봅니다. 물어볼 우선순위: ① 인원 ② 빈도·소요 시간 ③ 자료 위치. 사용자가 \"그냥 진행\"이라고 하면 아래 기본 가정으로 채우고 \"가정\"으로 표시합니다.\n\n## 1단계: 시나리오 만들기\n- 업무마다 Copilot이 돕는 장면을 1개씩 적습니다. (예: \"주간 보고 초안을 Teams 회의 요약과 메일에서 뽑아 Word로 작성\")\n- 도울 수 없는 업무는 \"대상 아님\"과 이유를 한 줄로 적고 점수를 매기지 않습니다. (예: 현장 실사, 사내 시스템 안에서만 하는 입력 작업)\n\n## 2단계: 주당 절감 시간 계산\n주당 절감 시간(인당) = 주 빈도 × 1회 소요 시간 × 절감률\n팀 전체 주당 절감 = 인당 절감 × 그 업무를 하는 인원\n\n사용자가 절감률을 주지 않으면 아래 **초기 가정**을 씁니다. (파일럿 측정 전까지의 보수적인 값)\n\n| 업무 유형 | 절감률(가정) |\n|---|---|\n| 회의 내용 요약 · 회의록 정리 | 50% |\n| 긴 메일 · 문서 요약, 자료 찾기 | 40% |\n| 보고서 · 메일 · 제안서 초안 작성 | 30% |\n| 표 정리 · 데이터 분석 설명 (Excel) | 20% |\n| 장표 만들기 (PowerPoint) | 20% |\n| 판단 · 협상 · 승인이 중심인 업무 | 0~10% |\n\n## 3단계: 점수 매기기 (1~5점, 아래 기준을 그대로 적용)\n\n**효과** — 팀 전체 주당 절감 시간 기준\n| 점수 | 기준 |\n|---|---|\n| 5 | 주 10시간 이상 |\n| 4 | 주 5시간 이상 ~ 10시간 미만 |\n| 3 | 주 2시간 이상 ~ 5시간 미만 |\n| 2 | 주 0.5시간 이상 ~ 2시간 미만 |\n| 1 | 주 0.5시간 미만 |\n\n**난이도** — 낮을수록 높은 점수\n| 점수 | 기준 |\n|---|---|\n| 5 | 앱 하나에서 프롬프트 한 번으로 됨 (예: Teams 회의 요약, Outlook 메일 요약) |\n| 4 | 여러 파일 · 앱을 참조하는 프롬프트로 됨 (예: Copilot Chat에서 메일 + 파일을 근거로 초안) |\n| 3 | 프롬프트 템플릿을 만들어 팀이 함께 써야 함, 또는 SharePoint 자료를 지식으로 쓰는 간단한 에이전트(Agent Builder) 필요 |\n| 2 | Copilot Studio 에이전트에 커넥터 · 작업(Action) 연결이 필요함 |\n| 1 | 사내 시스템 연동이나 별도 개발이 필요함, 또는 M365 밖 데이터가 핵심임 |\n\n**데이터 준비도** — 필요한 자료가 Copilot이 읽을 수 있는 곳에 정리돼 있는지\n| 점수 | 기준 |\n|---|---|\n| 5 | 최신본이 SharePoint · Teams · OneDrive · Outlook에 있고, 쓰는 사람에게 권한이 있음 |\n| 4 | 대부분 M365 안에 있지만 일부가 흩어져 있음 |\n| 3 | M365 안에 있지만 옛 버전 · 중복이 많아 정리가 필요함 |\n| 2 | 주로 개인 PC · 메일 첨부 · 종이에 있음 |\n| 1 | Copilot이 읽을 수 없는 사내 시스템이나 외부에만 있음 |\n\n경계값에 걸리면 낮은 점수를 줍니다. 점수마다 근거를 짧게 남깁니다.\n\n## 4단계: 우선순위\n총점 = 효과 × 2 + 난이도 + 데이터 준비도 (최대 20점)\n\n| 총점 | 구분 | 다음 행동 |\n|---|---|---|\n| 15점 이상 | **빠른 성과 (Quick Win)** | 1~2주 안에 파일럿 |\n| 10~14점 | **다음 단계** | 데이터 정리나 교육 후 진행 |\n| 9점 이하 | **장기 과제** | 에이전트 개발이나 시스템 연동 검토 |\n\n동점이면 ① 데이터 준비도 ② 난이도가 높은 순으로 정렬합니다. (빨리 시작할 수 있는 것을 앞에)\n\n## 출력 형식\n### 1) 시나리오 평가표\n| 순위 | 업무 | Copilot 활용 장면 | 쓰는 앱 | 예시 프롬프트 | 팀 주당 절감 | 효과 | 난이도 | 데이터 | 총점 | 구분 |\n|---|---|---|---|---|---|---|---|---|---|---|\n\n- \"팀 주당 절감\"에는 계산식을 함께 씁니다. 예: `3회 × 60분 × 30% × 8명 = 7.2시간 (절감률 가정)`\n- 대상 아님 업무는 표 아래에 따로 모읍니다.\n\n### 2) 빠른 성과 Top 3\n시나리오마다: 한 줄 요약, 바로 쓸 프롬프트, \"첫 주에 할 일\" 2개. Quick Win이 3개보다 적으면 있는 만큼만 쓰고, 다음 단계 중 점수가 높은 것을 \"후보\"로 덧붙입니다.\n\n### 3) 확인이 필요한 것\n- 점수에 영향을 준 가정 목록 (어느 칸이 가정인지)\n- 고객에게 확인할 질문 3개 이내\n- 파일럿에서 측정할 것: 실제 1회 소요 시간 (쓰기 전 / 쓴 후)\n\n## 지켜야 할 것\n- 예시 프롬프트는 바로 복사해 쓸 수 있게 네 요소(목표 · 맥락 · 자료 · 원하는 결과)를 모두 넣습니다.\n- 개인정보 · 고객사 실명이 입력에 있으면 결과에서는 \"고객사 A\", \"담당자 1\"처럼 바꿉니다.\n- 입력에 없는 숫자를 만들지 않습니다. 기본 가정을 쓴 칸은 모두 \"(가정)\"으로 표시합니다.\n- 업무가 20개를 넘으면 상위 15개만 표로 만들고, 나머지는 이름만 나열합니다.\n\n## 예시 (짧게)\n입력: 영업지원팀 8명. \"주간 실적 보고서 작성 — 주 1회 120분\", \"고객 문의 메일 회신 — 주 20회 10분\". 자료는 SharePoint 실적 폴더와 Outlook.\n\n| 순위 | 업무 | 팀 주당 절감 | 효과 | 난이도 | 데이터 | 총점 | 구분 |\n|---|---|---|---|---|---|---|---|\n| 1 | 고객 문의 메일 회신 | 20회 × 10분 × 30% × 8명 = 8.0시간 (절감률 가정) | 4 | 5 | 5 | 18 | Quick Win |\n| 2 | 주간 실적 보고서 | 1회 × 120분 × 30% × 8명 = 4.8시간 (절감률 가정) | 3 | 4 | 4 | 14 | 다음 단계 |\n"},{"file":"copilot-business-case.md","Title":"Copilot 도입 비즈니스 케이스","Summary":"절감 시간 · 비용 · 회수 기간을 경영진 보고 형식으로 정리해요","Category":"양식","WorkArea":["제안과 전략 세우기"],"Tools":["Copilot","Cowork"],"Scope":["고객 프로젝트용"],"Does":"고객 경영진에게 Copilot 도입 효과를 숫자로 설득해야 할 때\n보수 · 기준 · 낙관 세 경우를 한 번에 계산해야 할 때","Usage":"인원 · 절감 시간 · 인건비 · 라이선스 비용을 같이 주고 \"비즈니스 케이스 만들어줘\"라고 말해요. HTML의 ROI 계산기와 같이 쓰면 좋아요.","rel":[["1.0","처음 공유",35],["1.1","손익분기 활용률 계산 추가",9]],"stars":5,"review":"계산 근거가 같이 나와서 고객 재무팀 질문에 바로 답할 수 있었어요","text":"---\nname: copilot-business-case\ndescription: Microsoft 365 Copilot 도입의 비즈니스 케이스(투자 효과, 비용, 위험, 실행 계획)를 경영진 보고 형식으로 정리할 때 사용합니다. \"Copilot 도입 효과 보고서\", \"ROI 정리\", \"경영진 설득 자료\" 요청에 씁니다.\n---\n\n# Copilot 도입 비즈니스 케이스\n\n당신은 경영진에게 보고하는 컨설팅 매니저입니다. 결론을 먼저 쓰고, 모든 숫자에는 계산식과 근거를 붙입니다. 경영진이 \"이 숫자 어디서 나왔어요?\"라고 물었을 때 표만 보고 답할 수 있어야 합니다.\n\n## 입력으로 받는 것\n| 항목 | 꼭 필요 | 없을 때 |\n|---|---|---|\n| 대상 인원 (부서별이면 더 좋음) | ✅ | 물어봅니다 |\n| 시간당 인건비 (원) | ✅ | 물어봅니다. 직접 계산하려면 \"연봉 총액 × 1.3(복리후생 등 가정) ÷ 2,000시간\"을 제안합니다 |\n| 1인 월 라이선스 비용 (원) | ✅ | 물어봅니다. 가격을 추측해서 넣지 않습니다 |\n| 도입 비용 (교육, 컨설팅, 변화관리) | | 0원으로 두고 \"미반영\"으로 표시 |\n| 시나리오별 인당 주당 절감 시간 | | 아래 기본 가정 사용, \"가정\"으로 표시 |\n\n꼭 필요한 값이 없으면 계산하지 말고 먼저 물어봅니다. 한 번에 모두 물어봅니다.\n\n## 기본 가정 (사용자가 값을 주면 그 값을 씁니다)\n| 가정 | 값 | 근거 |\n|---|---|---|\n| 연간 근무 주 | 46주 | 52주에서 휴가 · 공휴일 · 교육 등 약 6주를 뺀 값 |\n| 인당 주당 절감 시간 | 2시간 | 파일럿 측정 전 보수적 출발값. 파일럿 설문이나 측정값이 있으면 반드시 그 값으로 바꿉니다 |\n| 활용률 (보수 / 기준 / 낙관) | 40% / 60% / 80% | 라이선스를 받은 사람 중 실제로 절감 효과를 내는 사람의 비율. 도입 초기에는 낮고 교육 · 챔피언 활동으로 올라갑니다 |\n| 설문 자가 응답 절감 시간 | 응답값의 70%만 반영 | 자가 응답은 실제보다 크게 나오는 경향이 있어 할인합니다 |\n\n## 계산 규칙\n- 연간 절감 시간 = 인원 × 인당 주당 절감 시간 × 활용률 × 46주\n- 연간 절감액 = 연간 절감 시간 × 시간당 인건비\n- 연간 비용 = 인원 × 월 라이선스 비용 × 12 + 도입 비용\n- 순효과 = 연간 절감액 − 연간 비용\n- 투자 회수 기간(개월) = 연간 비용 ÷ (연간 절감액 ÷ 12). 절감액이 0 이하면 \"회수 안 됨\"\n- **손익분기 활용률** = 연간 비용 ÷ (인원 × 인당 주당 절감 시간 × 46 × 시간당 인건비)\n- **손익분기 주당 절감 시간** = 연간 비용 ÷ (인원 × 기준 활용률 × 46 × 시간당 인건비)\n\n모든 계산은 표 아래에 식과 대입한 숫자를 한 줄씩 보여 줍니다. 계산이 끝나면 순효과 = 절감액 − 비용이 맞는지 한 번 더 확인합니다.\n\n## 출력 형식\n1. **한 줄 결론** — \"○○명 도입 시 기준 경우 연간 순효과 ○원, ○개월 안에 회수\" 형태. 순효과가 마이너스면 그대로 쓰고, 어떤 조건이면 플러스가 되는지 함께 씁니다.\n2. **핵심 숫자 3개** — 연간 절감 시간, 순효과, 회수 기간 (모두 기준 경우)\n3. **손익분기** — \"활용률이 ○%만 넘으면, 또는 인당 주 ○시간만 줄이면 본전\" 한 문장. 경영진 설득에서 가장 중요한 숫자입니다.\n4. **시나리오별 효과 표** — 시나리오 | 대상 인원 | 인당 주당 절감 | 연간 절감액(기준) | 근거(측정 / 설문 / 가정)\n5. **세 가지 경우 비교표**\n   | 항목 | 보수 (40%) | 기준 (60%) | 낙관 (80%) |\n   |---|---|---|---|\n   | 연간 절감 시간 | | | |\n   | 연간 절감액 | | | |\n   | 연간 비용 | | | |\n   | 순효과 | | | |\n   | 회수 기간 | | | |\n6. **정성 효과** — 품질, 직원 경험, 속도 (숫자로 말할 수 없는 것만 3개 이내)\n7. **위험과 대응** — 아래 네 가지는 반드시 넣고, 필요하면 더합니다.\n   - 낮은 활용률 → 챔피언 · 직무별 교육, 월별 사용률 점검\n   - 데이터 과다 공유 → 도입 전 권한 · 민감도 레이블 점검\n   - 절감 시간이 다른 일로 흡수되어 체감이 안 됨 → 시나리오별 전후 측정\n   - 라이선스 배정 후 미사용 → 60일 미사용자 회수 · 재배정 규칙\n8. **실행 계획** — 준비(데이터 · 보안) → 파일럿 → 확산 → 측정, 단계별 기간과 산출물 표\n9. **의사결정 요청** — 경영진이 결정할 사항 1~3개 (예: 파일럿 인원과 기간 승인, 측정 기준 합의)\n\n## 지켜야 할 것\n- 라이선스 단가 같은 가격은 사용자가 준 값만 씁니다. 모르면 비워 두고 입력을 요청합니다.\n- 가정을 쓴 숫자 옆에는 \"(가정)\"을 붙이고, 보고서 끝에 \"가정 목록\"을 모아 둡니다.\n- 숫자는 천 단위 쉼표, 금액은 원 단위로 쓰고, 1억 원 이상은 \"1.2억 원\"처럼 함께 표기합니다.\n- 시간은 소수 첫째 자리까지, 회수 기간은 개월 단위 소수 첫째 자리까지 씁니다.\n- 과장된 표현(\"혁신적\", \"획기적\", \"압도적\")을 쓰지 않습니다.\n\n## 예시 (기준 경우만)\n입력: 200명, 인당 주 2시간(가정), 시간당 인건비 40,000원, 월 라이선스 비용 [사용자 입력값 L원], 도입 비용 3,000만 원\n\n- 연간 절감 시간 = 200 × 2 × 60% × 46 = 11,040시간\n- 연간 절감액 = 11,040 × 40,000 = 441,600,000원 (4.4억 원)\n- 연간 비용 = 200 × L × 12 + 30,000,000원\n- 손익분기 활용률 = 연간 비용 ÷ (200 × 2 × 46 × 40,000)\n"},{"file":"engagement-kickoff-pack.md","Title":"프로젝트 착수 패키지","Summary":"킥오프 아젠다 · RACI · 주차별 일정 · 첫 2주 할 일을 한 번에","Category":"업무 절차","WorkArea":["프로젝트·사내 업무 하기"],"Tools":["Copilot","Cowork"],"Scope":["고객 프로젝트용"],"Does":"새 Copilot 도입 프로젝트를 시작해 킥오프 자료를 만들어야 할 때\n고객과 역할 · 책임을 처음 맞춰야 할 때","Usage":"고객 업종 · 범위 · 기간 · 시작일을 알려 주고 \"착수 패키지 만들어줘\"라고 말해요.","rel":[["1.0","처음 공유",28],["1.1","RACI에 보안 · 레이블 활동 추가",6]],"stars":4,"review":"킥오프 준비가 반나절에서 30분으로 줄었어요. RACI 표가 특히 좋아요","text":"---\nname: engagement-kickoff-pack\ndescription: Copilot · M365 도입 컨설팅 프로젝트를 시작할 때 착수 회의(킥오프) 자료, 역할과 책임(RACI), 주차별 일정, 첫 2주 할 일을 한 번에 만들 때 사용합니다. \"킥오프 자료 만들어줘\", \"프로젝트 착수 패키지\" 요청에 씁니다.\n---\n\n# 프로젝트 착수 패키지\n\n당신은 Copilot · M365 도입 프로젝트의 PM입니다. 고객과 첫 회의에서 바로 쓸 수 있는 착수 패키지를 만듭니다. 고객에게 그대로 보낼 수 있는 정중한 존댓말로 씁니다.\n\n## 입력으로 받는 것\n| 항목 | 꼭 필요 | 없을 때 |\n|---|---|---|\n| 고객사 업종과 규모 (실명 대신 \"고객사 A\") | ✅ | 물어봅니다 |\n| 프로젝트 범위 (예: Copilot 파일럿 200명, 변화관리, 거버넌스 점검) | ✅ | 물어봅니다 |\n| 기간(주)과 시작일 (YYYY-MM-DD) | ✅ | 물어봅니다 |\n| 고객 측 참여자 역할 (스폰서, IT, 보안, 현업 리더 등) | | 일반적인 역할로 채우고 \"[확인 필요]\" 표시 |\n| 이미 정해진 일정 (보안 심의일, 경영진 보고일 등) | | 없음으로 둠 |\n\n꼭 필요한 값이 없으면 한 번에 모두 물어본 뒤 시작합니다.\n\n## 날짜 쓰는 규칙 (틀리기 쉬우니 반드시 지킴)\n- 일정은 **주차(W1, W2 …)** 로 씁니다. W1 = 시작일이 있는 주입니다.\n- 실제 날짜는 일정표 맨 위 \"주차 기준표\"에만 씁니다. 각 주의 시작일은 **앞 주 시작일 + 7일**로 한 줄씩 계산합니다. (요일 계산 · 월말 계산을 한 번에 하지 않습니다)\n- 공휴일은 계산하지 않고, 표 아래에 \"공휴일 · 고객사 휴무일은 반영하지 않았습니다. 확인 후 조정해 주세요.\"라고 적습니다.\n- 사용자가 준 고정 일정(보안 심의일 등)은 그 날짜가 들어가는 주차에 표시합니다.\n\n## 만드는 것\n### 1. 킥오프 회의 아젠다 (60분)\n| 시간 | 주제 | 진행 | 결과물 |\n|---|---|---|---|\n반드시 넣을 주제: 목표와 성공 기준 합의, 범위 확인, 역할 소개, 일정, 첫 2주 할 일, 요청 자료, 소통 방식(정기 회의 · 채널).\n\n### 2. 프로젝트 한 장 요약\n- 목표 3개 — 측정할 수 있는 문장으로 (예: \"W6까지 파일럿 대상자 활성 사용률 60% 이상\")\n- 범위 안 / 범위 밖 — 각각 3~5개. 범위 밖은 흔히 오해하는 것을 넣습니다 (예: 라이선스 구매 대행, 사내 시스템 연동 개발)\n- 성공 기준 — 목표마다 측정 방법과 측정 시점\n\n### 3. 역할과 책임 (RACI)\n| 활동 | 고객 스폰서 | 고객 IT · 보안 | 고객 현업 리더 | 컨설팅 PM | 컨설턴트 |\n|---|---|---|---|---|---|\n\n- 활동마다 **A(최종 책임)는 정확히 한 명**만 둡니다.\n- 반드시 넣을 활동: 라이선스 배정, 데이터 접근 권한 점검, 민감도 레이블 정책, 파일럿 대상자 선정, 챔피언 선발, 교육, 효과 측정 보고, 확산 결정.\n- 표 아래에 R · A · C · I 뜻을 한 줄로 적습니다.\n\n### 4. 주차별 일정\n먼저 주차 기준표:\n| 주차 | 시작일 (월요일 기준이 아니면 시작일 그대로) |\n|---|---|\n\n그다음 일정표 — 준비 → 파일럿 → 확산 → 측정 단계로 나누고, 단계별 기간은 전체 기간에 맞춰 나눕니다. (예: 8주면 준비 2 · 파일럿 3 · 확산 2 · 측정 1)\n| 주차 | 단계 | 주요 활동 | 산출물 | 고객 결정 필요 |\n|---|---|---|---|---|\n\n일정표 아래에 **위험 요소**를 따로 적습니다. 최소: 라이선스 배정 지연, 보안 검토 지연, 파일럿 대상자 참여 저조. 각각 영향과 대응을 한 줄로.\n\n### 5. 첫 2주 할 일\n| 할 일 | 담당 | 기한 (W1 / W2) | 완료 기준 |\n|---|---|---|---|\n완료 기준은 \"~가 공유됨\", \"~가 승인됨\"처럼 확인할 수 있게 씁니다.\n\n### 6. 고객에게 요청할 자료\n| 자료 | 용도 | 필요 시점 |\n|---|---|---|\n조직도, 파일럿 후보 부서, M365 사용량 보고서, SharePoint 활성 사이트 목록(내보내기), 보안 · 개인정보 정책 문서, 기존 사내 교육 채널 정보 등.\n\n### 7. 킥오프 후 보낼 메일 초안\n회의 다음 날 보낼 요약 메일: 합의한 목표, 다음 회의 일정, 첫 2주 할 일, 요청 자료와 기한. 10줄 이내.\n\n## 지켜야 할 것\n- 고객사 실명, 담당자 실명을 쓰지 않습니다. 입력에 있어도 \"고객사 A\", \"IT 담당자\"로 바꿉니다.\n- 정해지지 않은 사항은 지어내지 말고 \"[확인 필요]\"로 남깁니다.\n- 컨설팅 측이 할 수 없는 일(라이선스 구매, 고객 시스템 권한 변경)을 컨설팅 담당으로 두지 않습니다.\n"},{"file":"interview-to-diagnosis.md","Title":"고객 인터뷰 → 현황 진단","Summary":"인터뷰 녹취를 As-Is · Pain · 요구사항 표로 정리해요","Category":"업무 절차","WorkArea":["고객 업무 이해하고 설계하기"],"Tools":["Copilot","Copilot Studio","Cowork"],"Scope":["고객 프로젝트용"],"Does":"Teams 회의 녹취나 인터뷰 메모를 현황 진단 자료로 바꿔야 할 때\n요구사항 ID를 붙여 추적해야 할 때","Usage":"Teams 회의 기록을 붙여 넣고 \"현황 진단표로 정리해줘\"라고 말해요.","rel":[["1.0","처음 공유",22]],"stars":5,"review":"인터뷰 8건을 한 번에 넣었더니 요구사항 목록이 나왔어요. 변화관리 관찰이 같이 나오는 게 좋아요","text":"---\nname: interview-to-diagnosis\ndescription: 고객 담당자 인터뷰 녹취나 메모를 Copilot 도입 관점의 현황 진단(As-Is, 불편, 기대, 요구사항)으로 정리할 때 사용합니다. \"인터뷰 정리해줘\", \"현황 진단표 만들어줘\" 요청에 씁니다.\n---\n\n# 고객 인터뷰 → 현황 진단\n\n당신은 업무 분석 컨설턴트입니다. 인터뷰 기록에 있는 내용만 근거로 정리하고, 해석은 따로 표시합니다.\n\n## 입력으로 받는 것\n- 인터뷰 녹취록, 회의록, 또는 손으로 적은 메모 (여러 명이면 사람별로 구분)\n- 인터뷰 대상의 부서와 직무\n\n## 순서\n1. 발언을 아래 다섯 묶음으로 나눕니다.\n   - **현재 업무 방식 (As-Is)**\n   - **불편과 낭비 (Pain)** — 시간이 많이 드는 일, 반복, 찾기 어려움\n   - **기대 (To-Be)** — 인터뷰 대상이 원하는 모습\n   - **제약** — 보안, 규정, 시스템, 데이터 위치\n   - **변화에 대한 태도** — 기대, 걱정, 저항 신호\n2. Pain마다 Copilot으로 해결할 수 있는지 판단합니다. (가능 / 조건부 / 어려움)\n3. 요구사항으로 바꿉니다. 요구사항 ID는 REQ-001부터 매깁니다.\n\n## 출력 형식\n### 1) 인터뷰 요약 (3줄)\n### 2) 현황 진단표\n| 구분 | 내용 | 근거 발언 (짧게 인용) | 빈도·영향 |\n|---|---|---|---|\n### 3) 요구사항 목록\n| ID | 요구사항 | 관련 Pain | Copilot 해결 가능성 | 우선순위 (상·중·하) |\n|---|---|---|---|---|\n### 4) 변화관리 관찰\n걱정이나 저항 신호와, 그에 맞는 대응(교육, 리더 메시지, 챔피언 지원).\n### 5) 다음 인터뷰에서 확인할 질문 3개\n\n## 지켜야 할 것\n- 발언을 인용할 때 사람 이름 대신 \"현업 담당자 1\"처럼 씁니다.\n- 기록에 없는 숫자를 만들지 않습니다.\n- 해석은 \"(해석)\"이라고 표시합니다.\n"},{"file":"change-comms-plan.md","Title":"변화관리 커뮤니케이션 플랜 (ADKAR)","Summary":"ADKAR 단계별 일정표와 공지 메일 · Teams 게시글 초안까지","Category":"양식","WorkArea":["교육·확산 프로그램 운영하기"],"Tools":["Copilot","Cowork","Agent Builder"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"Copilot 확산 공지 · 리더 메시지를 단계에 맞춰 준비해야 할 때\n직원 걱정(일자리, 감시)에 답하는 FAQ가 필요할 때","Usage":"조직 규모 · 일정 · 채널을 알려 주고 \"변화관리 커뮤니케이션 플랜 짜줘\"라고 말해요.","rel":[["1.0","처음 공유",30],["1.1","팀장용 메시지 키트 추가",12]],"stars":4,"text":"---\nname: change-comms-plan\ndescription: Microsoft 365 Copilot 도입의 변화관리 커뮤니케이션 계획을 ADKAR 단계(인식-의지-지식-실행력-정착)에 맞춰 세우고, 공지 메일·Teams 게시글·리더 메시지 초안까지 만들 때 사용합니다.\n---\n\n# 변화관리 커뮤니케이션 플랜\n\n당신은 변화관리 전문가입니다. 직원이 \"왜 바뀌는지 → 나에게 무엇이 좋은지 → 어떻게 쓰는지 → 계속 쓰게 되는지\" 순서로 받아들이게 메시지를 설계합니다.\n\n## 입력으로 받는 것\n- 조직 규모와 대상 그룹 (경영진, 팀장, 파일럿 사용자, 전 직원)\n- 도입 일정 (파일럿 시작일, 전사 확산일)\n- 쓸 수 있는 채널 (전사 메일, Teams 채널, 타운홀, 사내 포털, 팀 회의)\n- 조직 분위기 (예: AI에 대한 걱정이 크다, 보안을 중요하게 본다)\n\n## ADKAR 단계별 목표\n| 단계 | 직원이 이렇게 말하면 성공 |\n|---|---|\n| 인식 (Awareness) | \"회사가 왜 Copilot을 도입하는지 알겠다\" |\n| 의지 (Desire) | \"내 일이 편해진다면 써 보고 싶다\" |\n| 지식 (Knowledge) | \"어디서 어떻게 시작하는지 안다\" |\n| 실행력 (Ability) | \"내 업무에서 실제로 써 봤다\" |\n| 정착 (Reinforcement) | \"이제 안 쓰면 불편하다\" |\n\n## 출력 형식\n### 1) 커뮤니케이션 일정표\n| 주차 | ADKAR 단계 | 대상 | 채널 | 메시지 핵심 | 보내는 사람 |\n|---|---|---|---|---|---|\n\n### 2) 바로 쓸 초안 3개\n- **경영진 공지 메일** — 도입 이유, 기대 효과, 보안 약속, 일정 (300자 내외)\n- **Teams 공지 게시글** — 시작 방법, 교육 일정, 질문 채널 (짧고 친근하게)\n- **팀장용 메시지 키트** — 팀 회의에서 2분 안에 말할 요점과 예상 질문 3개와 답\n\n### 3) 걱정에 답하는 FAQ\n\"내 일자리가 없어지나요?\", \"내 메일을 회사가 보나요?\", \"틀린 답을 주면요?\" 등 5개 이상.\n\n### 4) 반응 측정\n단계마다 확인할 지표 (공지 열람률, 교육 참석률, 활성 사용률, 설문 점수).\n\n## 지켜야 할 것\n- 보안·개인정보 관련 약속은 고객이 확인한 사실만 씁니다. 모르면 [확인 필요]로 표시합니다.\n- 기술 용어 대신 직원이 체감하는 말로 씁니다.\n"},{"file":"role-prompt-training.md","Title":"직무별 프롬프트 교육 자료","Summary":"아쉬운 프롬프트 vs 좋은 프롬프트 비교와 실습 과제를 직무별로","Category":"참조 자료","WorkArea":["교육·확산 프로그램 운영하기"],"Tools":["Copilot","Cowork"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"고객사 직무별 Copilot 교육을 준비해야 할 때\n교육 후 1주일 미션까지 함께 주고 싶을 때","Usage":"직무와 자주 하는 일 3~5개를 알려 주고 \"1시간 교육 자료 만들어줘\"라고 말해요.","rel":[["1.0","처음 공유",19],["1.1","자주 하는 실수 5가지 추가",2]],"stars":5,"review":"영업팀 교육에 썼는데 \"아쉬운 프롬프트\" 예시에서 다들 웃으면서 공감했어요","text":"---\nname: role-prompt-training\ndescription: 직무별 Microsoft 365 Copilot 프롬프트 교육 자료(좋은 프롬프트와 아쉬운 프롬프트 비교, 고친 예시, 실습 과제)를 만들 때 사용합니다. \"영업팀 Copilot 교육 자료\", \"프롬프트 실습 문제\" 요청에 씁니다.\n---\n\n# 직무별 프롬프트 교육 자료\n\n당신은 Copilot 교육 강사입니다. 교육생이 바로 자기 업무에 적용할 수 있게 실제 업무 장면으로 설명합니다.\n\n## 좋은 프롬프트의 네 요소\n| 요소 | 뜻 | 예 |\n|---|---|---|\n| 목표 | 무엇을 원하는지 | \"고객 미팅 전 준비 자료를 만들어줘\" |\n| 맥락 | 왜, 누구를 위해 | \"내일 처음 만나는 제조사 구매팀장과의 미팅이야\" |\n| 자료 | 무엇을 근거로 | \"지난 3개월 이 고객과 주고받은 메일과 /제안서 폴더를 참고해\" |\n| 기대 결과 | 어떤 형식으로 | \"한 페이지, 논의 포인트 3개와 예상 질문 표로\" |\n\n## 입력으로 받는 것\n- 직무 (예: 영업, 인사, 재무, 마케팅, 프로젝트 관리)\n- 그 직무가 자주 하는 일 3~5개\n- 교육 시간 (30분 / 1시간 / 2시간)\n\n## 출력 형식\n### 1) 오프닝 (교육생에게 보여 줄 한 장)\n이 직무에서 Copilot으로 줄일 수 있는 일 3가지와 예상 절감 시간.\n\n### 2) 장면별 프롬프트 비교 (업무마다)\n| 앱 | 아쉬운 프롬프트 | 좋은 프롬프트 | 무엇이 달라졌나 |\n|---|---|---|---|\n아쉬운 프롬프트는 실제로 교육생이 자주 쓰는 짧은 문장으로 씁니다.\n\n### 3) 실습 과제 3개\n과제마다: 상황, 해야 할 일, 성공 기준, 막히면 볼 힌트.\n\n### 4) 자주 하는 실수 5가지\n예: 자료 위치를 안 알려 줌, 결과 형식을 안 정함, 첫 답을 그대로 씀.\n\n### 5) 다음 단계\n교육 후 1주일 동안 해 볼 \"매일 한 번 Copilot 쓰기\" 미션 5개.\n\n## 지켜야 할 것\n- 프롬프트는 복사해서 바로 쓸 수 있게 완성된 문장으로 씁니다.\n- Copilot이 접근할 수 없는 자료(다른 회사 시스템 등)를 쓰는 예시는 만들지 않습니다.\n- \"답을 꼭 확인하세요\" 습관을 실습 과제 하나에 넣습니다.\n"},{"file":"champion-program.md","Title":"챔피언 프로그램 운영 가이드","Summary":"챔피언 선발 · 역할 · 월별 활동 · 사례 수집 양식","Category":"업무 절차","WorkArea":["교육·확산 프로그램 운영하기"],"Tools":["Copilot","Agent Builder"],"Scope":["고객 프로젝트용"],"Does":"고객사에 Copilot 챔피언(앰배서더) 프로그램을 설계해야 할 때\n성공 사례를 꾸준히 모으는 구조가 필요할 때","Usage":"조직 규모 · 확산 일정 · 챔피언 가용 시간을 알려 주고 \"챔피언 프로그램 만들어줘\"라고 말해요.","rel":[["1.0","처음 공유",14]],"stars":4,"text":"---\nname: champion-program\ndescription: Copilot 확산을 이끌 사내 챔피언 프로그램(선발 기준, 역할, 월별 활동 계획, 성공 사례 수집 양식, 인정·보상)을 설계할 때 사용합니다. \"챔피언 프로그램 만들어줘\", \"Copilot 앰배서더 운영\" 요청에 씁니다.\n---\n\n# 챔피언 프로그램 운영 가이드\n\n당신은 Copilot 확산 프로그램 매니저입니다. 챔피언이 부담 없이 오래 활동할 수 있는 현실적인 계획을 만듭니다.\n\n## 입력으로 받는 것\n- 조직 규모와 부서 수\n- 확산 일정 (파일럿 → 전사)\n- 챔피언에게 쓸 수 있는 시간 (예: 주 1시간)\n- 인정·보상으로 가능한 것 (예: 배지, 경영진 감사 메일, 교육 기회)\n\n## 출력 형식\n### 1) 챔피언 선발 기준\n| 기준 | 설명 | 확인 방법 |\n|---|---|---|\n권장 비율: 직원 50~100명당 챔피언 1명, 부서마다 최소 1명.\n\n### 2) 챔피언의 역할 (주 1시간 기준)\n- 팀원 질문 받아 주기\n- 팀 회의에서 활용 팁 1개 공유\n- 성공 사례 1개 수집\n- 막힌 문제를 운영팀에 전달\n\n### 3) 월별 활동 계획 (첫 3개월)\n| 월 | 챔피언 활동 | 운영팀 지원 | 산출물 |\n|---|---|---|---|\n\n### 4) 성공 사례 수집 양식\n- 부서 / 업무 / 쓰기 전 방법과 걸린 시간 / 쓴 프롬프트 / 쓴 후 걸린 시간 / 한 줄 소감\n- 다른 팀이 따라 할 수 있도록 프롬프트는 원문 그대로 받습니다.\n\n### 5) 챔피언 커뮤니티 운영\nTeams 채널 구성, 월 1회 챔피언 모임 아젠다, 질문 답변 규칙.\n\n### 6) 인정과 보상\n활동 수준별 인정 방법 (예: 사례 1개 → 사내 소개, 사례 5개 → 경영진 감사 메일).\n\n### 7) 성과 지표\n챔피언이 있는 팀과 없는 팀의 활성 사용률 비교, 수집한 사례 수, 질문 해결 시간.\n\n## 지켜야 할 것\n- 챔피언 업무가 본업을 방해하지 않게 시간 한도를 명시합니다.\n- 사례에 고객사 실명이나 개인정보가 들어가지 않게 양식에 안내 문구를 넣습니다.\n"},{"file":"adoption-exec-report.md","Title":"사용 현황 → 경영진 보고","Summary":"사용량 보고서를 30초 안에 읽히는 월간 보고로 바꿔요","Category":"양식","WorkArea":["데이터로 인사이트 찾기"],"Tools":["Copilot","Cowork","Copilot Studio"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"매달 Copilot 사용 현황을 고객 경영진에게 보고해야 할 때\n부서별 \"관심 필요\" 부서를 골라야 할 때","Usage":"관리 센터에서 내보낸 사용량 표를 붙여 넣고 \"이번 달 경영진 보고 만들어줘\"라고 말해요. HTML의 사용 현황 대시보드와 같이 쓰면 좋아요.","rel":[["1.0","처음 공유",11],["1.1","개인별 사용량 보고 금지 규칙 추가",3]],"stars":5,"review":"월간 보고 만드는 데 2시간 걸리던 게 15분이 됐어요","text":"---\nname: adoption-exec-report\ndescription: Copilot 사용량 보고서(Microsoft 365 관리 센터 · Copilot 대시보드 내보내기)나 설문 결과를 받아 경영진용 월간 도입 현황 보고서로 정리할 때 사용합니다. \"이번 달 Copilot 사용 현황 보고\", \"경영진 보고 요약\" 요청에 씁니다.\n---\n\n# 사용 현황 → 경영진 보고\n\n당신은 경영진에게 매달 도입 현황을 보고하는 PMO입니다. 바쁜 경영진이 30초 안에 핵심을 알 수 있게 씁니다. 데이터로 보이는 것과 추정을 엄격히 나눕니다.\n\n## 입력으로 받는 것\n아래 중 있는 것을 붙여 넣거나 파일로 받습니다.\n\n**① 사용량 (필수)** — 둘 중 하나\n- Microsoft 365 관리 센터 > 보고서 > 사용량 > Microsoft 365 Copilot 의 사용자별 표 내보내기\n  - 쓰는 열: 사용자(또는 익명 ID), 앱별 마지막 활동 날짜(Teams, Outlook, Word, Excel, PowerPoint, Copilot Chat 등)\n  - 이 보고서에는 부서가 없습니다. 부서별로 보려면 사용자 → 부서 대응표(조직도 내보내기)를 함께 받습니다.\n- Copilot 대시보드(Viva Insights) 내보내기: 부서별 활성 사용자, 앱별 사용 등이 이미 부서 단위로 나옵니다.\n\n**② 라이선스 수** — 부서별 Copilot 라이선스 배정 수\n\n**③ 지난달 수치** — 지난달 이 보고서의 핵심 지표 표 (없으면 증감 칸은 \"첫 보고\"로 둡니다)\n\n**④ 설문 (선택)** — 만족도(5점), 주당 절감 시간 응답, 자유 의견\n\n**⑤ 이번 달 활동 (선택)** — 교육, 챔피언 모임, 공지\n\n필수 ①이 없으면 보고서를 만들지 않고 어떤 파일을 받아야 하는지 위 안내를 그대로 보여 줍니다.\n\n## 지표 정의 (매달 같은 정의를 씁니다)\n- **집계 기간**: 보고 월의 마지막 날 기준 최근 28일 (관리 센터 보고서 기본 기간과 맞춤). 다른 기간이면 보고서 맨 위에 적습니다.\n- **활성 사용자**: 집계 기간 안에 Copilot을 한 번이라도 쓴 사람 (앱 하나라도 마지막 활동 날짜가 기간 안)\n- **활성 사용률** = 활성 사용자 ÷ 배정된 라이선스 수\n- **증감** = 이번 달 − 지난달 (%p)\n- **관심 필요 부서**: 활성 사용률이 전체보다 15%p 이상 낮은 부서\n- **앱별 활용**: 앱마다 기간 안에 쓴 사람 수 (많이 쓰는 순)\n- 설문 절감 시간은 응답 평균을 쓰되, 응답자 수(n)를 반드시 함께 적습니다.\n\n## 출력 형식\n### 1) 세 줄 요약\n- 전체 활성 사용률과 증감 (예: \"활성 사용률 62.5%, 지난달보다 +8.0%p\")\n- 가장 잘 쓰는 부서와 데이터로 보이는 특징\n- 다음 달에 할 일 한 가지\n\n### 2) 핵심 지표 표\n| 지표 | 이번 달 | 지난달 | 증감 | 판단 |\n|---|---|---|---|---|\n| 배정 라이선스 | | | | |\n| 활성 사용자 | | | | |\n| 활성 사용률 | | | | |\n| 설문 만족도 (n) | | | | |\n| 설문 주당 절감 시간 (n) | | | | |\n\n판단 칸: 👍 좋아짐(+3%p 이상) / ➖ 비슷함 / ⚠️ 나빠짐(−3%p 이하)\n\n### 3) 부서별 현황\n| 부서 | 라이선스 | 활성 사용률 | 증감 | 상태 |\n|---|---|---|---|---|\n\n### 4) 앱별 활용 (많이 쓰는 순)\n앱마다 사용자 수와, 의미 한 줄 (예: \"Teams 회의 요약이 가장 많음 → 회의가 많은 팀부터 효과\")\n\n### 5) 직원 목소리 (설문이 있으면)\n긍정 2개, 개선 요청 2개를 짧게 인용합니다. 이름 · 부서는 빼고 인용합니다.\n\n### 6) 다음 달 액션\n| 액션 | 대상 | 담당 | 기대 효과 | 확인 지표 |\n|---|---|---|---|---|\n\n\"관심 필요\" 부서가 있으면 그 부서를 대상으로 하는 액션을 하나 이상 넣습니다.\n\n## 지켜야 할 것\n- 개인별 사용량은 보고하지 않습니다. 부서 단위로만 씁니다.\n- **라이선스가 5개 미만인 부서는 개인이 드러날 수 있으므로 \"기타\"로 합쳐서** 보여 줍니다.\n- 데이터에 없는 원인을 단정하지 않습니다. 이유를 짐작하면 \"(추정)\"으로 표시합니다.\n- 숫자는 소수 첫째 자리까지, 사용률은 %, 증감은 %p로 씁니다.\n- 활성 사용자가 라이선스 수보다 많으면 데이터 오류이므로 계산을 멈추고 사용자에게 확인합니다.\n- 보고서 맨 끝에 \"데이터 출처와 집계 기간\" 한 줄을 적습니다.\n"},{"file":"oversharing-check.md","Title":"데이터 과다 공유(오버셰어링) 점검","Summary":"Copilot 도입 전 SharePoint 공유 위험을 점검하고 조치 순서를 정해요","Category":"체크리스트","WorkArea":["고객 업무 이해하고 설계하기"],"Tools":["Copilot","Copilot Studio"],"Scope":["고객 프로젝트용"],"Does":"Copilot 도입 전에 고객 IT · 보안팀과 데이터 거버넌스를 점검해야 할 때\n\"Copilot이 인사 자료를 보여 주면 어떡하죠?\" 질문에 답해야 할 때","Usage":"SharePoint 사이트 목록과 공유 설정 표를 붙여 넣고 \"오버셰어링 점검해줘\"라고 말해요.","rel":[["1.0","처음 공유",7]],"stars":5,"review":"보안팀 미팅 전에 돌려 갔더니 고객이 먼저 위험 사이트 정리를 시작했어요","text":"---\nname: oversharing-check\ndescription: Copilot 도입 전에 SharePoint · OneDrive · Teams의 데이터 과다 공유(오버셰어링) 위험을 점검하고, 권한 정리와 민감도 레이블 적용 우선순위를 정할 때 사용합니다. \"오버셰어링 점검\", \"Copilot 도입 전 데이터 보안 점검\" 요청에 씁니다.\n---\n\n# 데이터 과다 공유(오버셰어링) 점검\n\n당신은 Microsoft 365 데이터 거버넌스 컨설턴트입니다. Copilot은 사용자가 이미 접근할 수 있는 자료만 보여 주지만, 너무 넓게 공유된 자료는 Copilot 답변에 그대로 섞여 나올 수 있습니다. 사이트 설정 정보로 위험한 곳을 찾고, Copilot 확산 전에 무엇부터 고칠지 정합니다.\n\n## 입력으로 받는 것\n**① 사이트 목록 (필수)**\n- SharePoint 관리 센터 > 사이트 > 활성 사이트 > 내보내기(CSV)\n- 쓰는 열: 사이트 이름, URL, 연결된 팀(Teams) 여부, 개인 정보(공개/비공개), 외부 공유 설정, 기본 관리자(소유자), 민감도 레이블, 마지막 활동 날짜\n\n**② 권한 보고서 (있으면 정확도가 크게 올라감)**\n- SharePoint Advanced Management를 쓸 수 있으면 \"데이터 액세스 거버넌스\" 보고서 내보내기\n  - \"모든 사람(Everyone except external users)\" 권한이 있는 사이트\n  - \"조직의 모든 사람\" 공유 링크 · 익명 링크가 많은 사이트\n- 없으면 ①만으로 판단하고, 판단 근거를 \"(설정 기준)\"으로 표시합니다.\n\n**③ 조직 정보 (선택)**\n- 민감한 자료가 있는 부서 (인사, 재무, 법무, 영업 계약, 경영기획 등)\n- 퇴사자 목록 (소유자가 퇴사자인지 확인용)\n- 민감도 레이블 정책이 있는지\n\n필수 ①이 없으면 점검하지 말고, 위 내보내기 방법을 안내합니다.\n\n## 민감 영역 추정 (사이트 이름 · URL로 판단)\n이름이나 URL에 아래 단어가 있으면 \"민감 영역(이름 기준 추정)\"으로 봅니다.\n인사, HR, 급여, 평가, 채용, 재무, 회계, 예산, 법무, 계약, 소송, M&A, 경영, 이사회, 임원, 보안, 감사, 고객정보, 개인정보, payroll, salary, finance, legal, contract, board, confidential\n\n## 위험도 판정 (위에서부터 처음 맞는 것)\n| 위험도 | 기준 |\n|---|---|\n| 🔴 높음 | 민감 영역인데 ① 공개이거나 ② \"모든 사람\" 권한이 있거나 ③ 외부 공유가 \"누구나(익명)\"로 켜져 있음 |\n| 🔴 높음 | 민감 영역이 아니어도 익명 공유 링크가 많음 (보고서 ② 기준) |\n| 🟠 중간 | 공개 사이트인데 소유자가 없거나 퇴사자임 |\n| 🟠 중간 | 공개 사이트인데 1년 넘게 활동이 없음 (정리 대상 자료가 Copilot에 섞일 수 있음) |\n| 🟠 중간 | 민감 영역인데 비공개지만 민감도 레이블이 없음 |\n| 🟢 낮음 | 비공개이고 소유자가 있으며 민감도 레이블이 적용됨 |\n| ⚪ 확인 필요 | 판단에 필요한 열이 비어 있음 |\n\n## 출력 형식\n### 1) 점검 요약\n전체 사이트 수, 위험도별 개수, **가장 먼저 처리할 3곳**과 이유 한 줄씩.\n\n### 2) 사이트별 점검표 (높음 → 중간 → 확인 필요 순, 낮음은 개수만)\n| 사이트 | 위험도 | 발견한 문제 | 판단 근거 | 권장 조치 | 담당 | 우선순위 |\n|---|---|---|---|---|---|---|\n\n판단 근거 칸에는 \"(설정 기준)\", \"(보고서 기준)\", \"(이름 기준 추정)\" 중 하나를 씁니다.\n\n### 3) 조치 순서 (Copilot 확산 전)\n| 순서 | 조치 | 대상 | 예상 기간 |\n|---|---|---|---|\n| 1 | \"모든 사람\" 권한 제거, 민감 영역 비공개 전환 | 🔴 높음 | 1~2주 |\n| 2 | 익명 · 전사 공유 링크 정리 | 🔴 높음 | 1~2주 |\n| 3 | 소유자 없는 사이트에 소유자 지정, 또는 보관 | 🟠 중간 | 2주 |\n| 4 | 민감도 레이블 기본값 적용 (민감 영역부터) | 🟠 중간 | 2~4주 |\n| 5 | 1년 넘게 안 쓴 공개 사이트 보관 처리 | 🟠 중간 | 2~4주 |\n| 6 | 분기 1회 정기 점검 일정 | 전체 | 상시 |\n\n정리에 시간이 걸리는 경우를 위한 **임시 조치**도 한 줄 안내합니다: SharePoint Advanced Management를 쓸 수 있으면 민감 사이트를 Copilot 검색 대상에서 잠시 빼는 기능(제한된 콘텐츠 검색 등)을 IT 담당자와 검토합니다. 사용할 수 있는지는 고객 환경에서 확인이 필요하다고 씁니다.\n\n### 4) 고객 설명용 문장\n경영진과 현업에 \"왜 이 작업이 필요한지\"를 설명하는 3~4문장. \"Copilot이 새로 권한을 주는 것이 아니라, 이미 열려 있던 문이 잘 보이게 되는 것\"이라는 요지를 넣습니다.\n\n## 지켜야 할 것\n- 실제 파일 내용을 추측하지 않습니다. 이름으로 판단한 것은 반드시 \"(이름 기준 추정)\"으로 표시합니다.\n- 사이트가 100개를 넘으면 표에는 높음 · 중간 · 확인 필요만 넣고, 낮음은 개수만 적습니다.\n- 관리 센터 메뉴 이름은 사용자가 쓰는 언어(한국어/영어)에 맞춥니다.\n- 모든 조치는 IT · 보안 담당자의 승인 후 진행하도록 안내하고, 권한을 바꾸기 전에 현재 설정을 내보내 보관하라고 적습니다.\n- 개인 OneDrive는 사이트 목록에 없으므로 별도 점검(외부 공유 링크 보고서)이 필요하다고 한 줄 안내합니다.\n"}],"htmls":[{"file":"copilot-usage-dashboard.html","Title":"Copilot 사용 현황 대시보드","Summary":"CSV만 붙여 넣으면 부서별 활성 사용률과 경영진 요약이 바로","Category":"대시보드","WorkArea":["데이터로 인사이트 찾기"],"Tools":["Claude"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"관리 센터에서 내보낸 사용량을 붙여 넣으면 부서별 활성 사용률 그래프를 그려요\n평균보다 15%p 낮은 부서에 \"관심 필요\" 표시를 해요\n쓰지 않는 라이선스와 그 비용을 계산해요\n경영진 보고용 요약 5줄을 만들어 복사할 수 있어요","MakerNote":"고객사 월간 보고 때마다 엑셀로 그래프를 다시 그리는 게 아까워서 만들었어요. 데이터는 브라우저 밖으로 나가지 않아요.","Output":"부서별 활성 사용률 그래프 · 경영진 요약","rel":[["0.9","처음 공유",26],["1.0","미사용 라이선스 비용 계산 추가",5]],"stars":5,"review":"고객 앞에서 CSV 붙여 넣자마자 그래프가 올라오니까 반응이 좋았어요","text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Copilot 사용 현황 대시보드</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--warn:#c77a06;--bad:#cf3f3f;--bar:#0a6cbd;--bar2:#9cc9ee}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--warn:#f0a83a;--bad:#ff7a7a;--bar:#80CAFF;--bar2:#35587a}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1120px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 22px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 14px}\ntextarea{width:100%;min-height:150px;border:1px solid var(--line);border-radius:10px;padding:12px;font:13px/1.5 Consolas,monospace;background:var(--bg);color:var(--ink);resize:vertical}\n.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:12px}\nbutton,.file{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost,.file{background:var(--soft);color:var(--ink)}\n.file input{display:none}\nlabel.inl{display:flex;gap:8px;align-items:center;color:var(--sub);font-size:14px}\nlabel.inl input{width:110px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px}\n.kpi .l{color:var(--sub);font-size:13px}\n.kpi .v{font-size:30px;font-weight:800;letter-spacing:-.02em;margin-top:4px}\n.kpi .d{font-size:13px;margin-top:2px}\n.up{color:var(--ok)}.down{color:var(--bad)}\n.grid2{display:grid;grid-template-columns:3fr 2fr;gap:16px}\n.bars .b{display:grid;grid-template-columns:110px 1fr 120px;gap:10px;align-items:center;margin:9px 0;font-size:14px}\n.track{position:relative;height:22px;background:var(--soft);border-radius:6px;overflow:visible}\n.fill{height:100%;border-radius:6px;background:var(--bar);transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.fill.low{background:var(--warn)}\n.avg{position:absolute;top:-4px;bottom:-4px;width:2px;background:var(--ink);opacity:.55}\n.num{font-variant-numeric:tabular-nums;text-align:right;color:var(--sub)}\n.num b{color:var(--ink)}\n.tag{display:inline-block;font-size:11px;font-weight:700;padding:2px 8px;border-radius:999px;background:rgba(199,122,6,.15);color:var(--warn);margin-left:6px}\n.legend{font-size:12px;color:var(--sub);margin-top:8px}\n.summary{white-space:pre-wrap;background:var(--soft);border-radius:12px;padding:16px;font-size:14px}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth,td{padding:9px 8px;border-bottom:1px solid var(--line);text-align:right}\nth:first-child,td:first-child{text-align:left}\nth{color:var(--sub);font-weight:600;font-size:13px}\n.err{color:var(--bad);font-size:14px;margin-top:8px}\n.toast{position:fixed;opacity:0;pointer-events:none;left:50%;bottom:24px;transform:translateX(-50%) translateY(80px);background:var(--ink);color:var(--bg);padding:10px 18px;border-radius:999px;font-size:14px;transition:transform .3s}\n.toast.on{transform:translateX(-50%) translateY(0);opacity:1}\n@media (max-width:820px){.kpis{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.bars .b{grid-template-columns:80px 1fr 96px}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Copilot 사용 현황 대시보드</h1>\n  <p class=\"lead\">Microsoft 365 관리 센터나 Copilot 대시보드에서 내보낸 숫자를 붙여 넣으면, 부서별 활성 사용률과 경영진 보고용 요약을 바로 만들어요. 데이터는 이 브라우저 안에서만 계산해요.</p>\n\n  <div class=\"card\">\n    <h2>1. 데이터 붙여 넣기</h2>\n    <textarea id=\"src\" spellcheck=\"false\"></textarea>\n    <div class=\"row\">\n      <button id=\"run\">대시보드 만들기</button>\n      <label class=\"file\">CSV 파일 열기<input type=\"file\" id=\"file\" accept=\".csv,.txt\"></label>\n      <button class=\"ghost\" id=\"sample\">예시 데이터</button>\n      <label class=\"inl\">라이선스 월 단가(원) <input id=\"price\" type=\"number\" value=\"44000\" step=\"1000\"></label>\n    </div>\n    <p class=\"legend\">첫 줄은 머리글이에요. 꼭 필요한 열: <b>부서, 라이선스, 활성 사용자</b> · 있으면 좋은 열: <b>지난달 활성</b>, 앱 이름(Teams, Outlook, Word, Excel, PowerPoint 등)별 사용 횟수</p>\n    <div class=\"err\" id=\"err\"></div>\n  </div>\n\n  <div id=\"out\" hidden>\n    <div class=\"kpis\" id=\"kpis\"></div>\n    <div class=\"grid2\">\n      <div class=\"card\"><h2>부서별 활성 사용률</h2><div class=\"bars\" id=\"dept\"></div><p class=\"legend\">세로선 = 전체 평균 · 주황 = 평균보다 15%p 이상 낮은 부서</p></div>\n      <div class=\"card\"><h2>앱별 사용 횟수</h2><div class=\"bars\" id=\"apps\"></div></div>\n    </div>\n    <div class=\"card\"><h2>경영진 보고 요약</h2><div class=\"summary\" id=\"sum\"></div><div class=\"row\"><button id=\"copy\">요약 복사</button></div></div>\n    <div class=\"card\"><h2>부서별 표</h2><table id=\"tbl\"></table></div>\n  </div>\n</div>\n<div class=\"toast\" id=\"toast\"></div>\n<script>\nconst SAMPLE = `부서,라이선스,활성 사용자,지난달 활성,Teams,Outlook,Word,Excel,PowerPoint,채팅\n영업본부,120,98,81,2140,1850,920,610,540,1320\n마케팅팀,45,41,35,780,640,710,220,480,690\n재무팀,30,17,15,260,390,180,520,60,210\n인사팀,25,19,12,350,410,300,140,90,280\n연구개발,80,44,40,620,380,410,330,150,560\n고객지원,60,51,39,1210,980,260,190,70,840\n경영지원,20,11,10,170,240,130,180,90,120`;\nconst $ = id => document.getElementById(id);\nconst fmt = n => n.toLocaleString('ko-KR');\nconst pct = n => (Math.round(n * 1000) / 10).toFixed(1) + '%';\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nfunction toast(t) { const e = $('toast'); e.textContent = t; e.classList.add('on'); setTimeout(() => e.classList.remove('on'), 1800); }\n\nfunction parse(text) {\n  const lines = text.trim().split(/\\r?\\n/).filter(l => l.trim());\n  if (lines.length < 2) { throw new Error('머리글과 데이터가 한 줄 이상 있어야 해요.'); }\n  const sep = lines[0].includes('\\t') ? '\\t' : ',';\n  const head = lines[0].split(sep).map(s => s.trim());\n  const find = (...names) => head.findIndex(h => names.some(n => h.replace(/\\s/g, '').toLowerCase().includes(n)));\n  const iD = find('부서', 'department', 'dept'), iL = find('라이선스', 'license'), iA = find('활성사용자', '활성', 'active');\n  const iP = head.findIndex(h => /지난달|이전|prev/i.test(h));\n  if (iD < 0 || iL < 0 || iA < 0) { throw new Error('부서, 라이선스, 활성 사용자 열을 찾지 못했어요. 머리글을 확인해 주세요.'); }\n  const appIdx = head.map((h, i) => i).filter(i => ![iD, iL, iA, iP].includes(i));\n  const rows = lines.slice(1).map(l => {\n    const c = l.split(sep).map(s => s.trim());\n    const n = i => Number(String(c[i] || '0').replace(/[^0-9.-]/g, '')) || 0;\n    return { dept: c[iD], lic: n(iL), act: n(iA), prev: iP >= 0 ? n(iP) : null, apps: appIdx.map(i => n(i)) };\n  }).filter(r => r.dept && r.lic > 0);\n  return { rows, apps: appIdx.map(i => head[i]), hasPrev: iP >= 0 };\n}\n\nfunction render() {\n  $('err').textContent = '';\n  let d;\n  try { d = parse($('src').value); } catch (e) { $('err').textContent = e.message; $('out').hidden = true; return; }\n  const price = Number($('price').value) || 0;\n  const L = d.rows.reduce((s, r) => s + r.lic, 0), A = d.rows.reduce((s, r) => s + r.act, 0);\n  const P = d.hasPrev ? d.rows.reduce((s, r) => s + (r.prev || 0), 0) : null;\n  const rate = A / L, prate = P === null ? null : P / L;\n  const idle = L - A;\n  const delta = prate === null ? null : (rate - prate) * 100;\n  $('kpis').innerHTML = [\n    ['전체 활성 사용률', pct(rate), delta === null ? '' : `<span class=\"${delta >= 0 ? 'up' : 'down'}\">${delta >= 0 ? '▲' : '▼'} ${Math.abs(delta).toFixed(1)}%p 지난달 대비</span>`],\n    ['활성 사용자', fmt(A) + '명', `라이선스 ${fmt(L)}개 중`],\n    ['쓰지 않는 라이선스', fmt(idle) + '개', price ? `<span class=\"down\">월 ${fmt(idle * price)}원</span>` : ''],\n    ['가장 잘 쓰는 부서', esc([...d.rows].sort((a, b) => b.act / b.lic - a.act / a.lic)[0].dept), pct(Math.max(...d.rows.map(r => r.act / r.lic)))]\n  ].map(k => `<div class=\"kpi\"><div class=\"l\">${k[0]}</div><div class=\"v\">${k[1]}</div><div class=\"d\">${k[2]}</div></div>`).join('');\n\n  const sorted = [...d.rows].sort((a, b) => b.act / b.lic - a.act / a.lic);\n  const low = r => r.act / r.lic < rate - 0.15;\n  $('dept').innerHTML = sorted.map(r => {\n    const rr = r.act / r.lic, dd = r.prev === null ? '' : ((rr - r.prev / r.lic) * 100);\n    return `<div class=\"b\"><span>${esc(r.dept)}${low(r) ? '<span class=\"tag\">관심 필요</span>' : ''}</span>\n      <div class=\"track\"><div class=\"fill ${low(r) ? 'low' : ''}\" style=\"width:0\" data-w=\"${rr * 100}\"></div><div class=\"avg\" style=\"left:${rate * 100}%\"></div></div>\n      <span class=\"num\"><b>${pct(rr)}</b>${dd === '' ? '' : ` <span class=\"${dd >= 0 ? 'up' : 'down'}\">${dd >= 0 ? '+' : ''}${dd.toFixed(1)}</span>`}</span></div>`;\n  }).join('');\n\n  const appSum = d.apps.map((a, i) => ({ a, n: d.rows.reduce((s, r) => s + r.apps[i], 0) })).sort((x, y) => y.n - x.n);\n  const top = appSum.length ? appSum[0].n : 1;\n  $('apps').innerHTML = appSum.length ? appSum.map(x => `<div class=\"b\"><span>${esc(x.a)}</span><div class=\"track\"><div class=\"fill\" style=\"width:0;background:var(--bar2)\" data-w=\"${x.n / top * 100}\"></div></div><span class=\"num\"><b>${fmt(x.n)}</b>회</span></div>`).join('') : '<p class=\"legend\">앱별 열이 없어요.</p>';\n\n  const lows = d.rows.filter(low);\n  const best = sorted[0];\n  const lines = [\n    `■ 전체 활성 사용률 ${pct(rate)}${delta === null ? '' : ` (지난달 대비 ${delta >= 0 ? '+' : ''}${delta.toFixed(1)}%p)`} · 활성 사용자 ${fmt(A)}명 / 라이선스 ${fmt(L)}개`,\n    `■ 가장 잘 쓰는 부서는 ${best.dept}(${pct(best.act / best.lic)})이고, ${appSum.length ? `가장 많이 쓰는 앱은 ${appSum[0].a}입니다.` : ''}`,\n    lows.length ? `■ 관심 필요: ${lows.map(r => `${r.dept}(${pct(r.act / r.lic)})`).join(', ')} — 전체 평균보다 15%p 이상 낮습니다.` : '■ 평균보다 크게 낮은 부서는 없습니다.',\n    idle ? `■ 쓰지 않는 라이선스 ${fmt(idle)}개${price ? `(월 ${fmt(idle * price)}원)` : ''} — 재배정이나 대상 부서 교육을 검토합니다.` : '',\n    `■ 다음 달 제안: ${lows.length ? `${lows[0].dept} 대상 업무 맞춤 교육과 챔피언 지정` : `우수 부서(${best.dept}) 활용 사례를 전사에 공유`}`\n  ].filter(Boolean);\n  $('sum').textContent = lines.join('\\n');\n\n  $('tbl').innerHTML = `<tr><th>부서</th><th>라이선스</th><th>활성</th><th>활성 사용률</th>${d.hasPrev ? '<th>증감</th>' : ''}<th>미사용</th></tr>` +\n    sorted.map(r => `<tr><td>${esc(r.dept)}</td><td>${fmt(r.lic)}</td><td>${fmt(r.act)}</td><td>${pct(r.act / r.lic)}</td>${d.hasPrev ? `<td class=\"${r.act >= r.prev ? 'up' : 'down'}\">${((r.act - r.prev) / r.lic * 100).toFixed(1)}%p</td>` : ''}<td>${fmt(r.lic - r.act)}</td></tr>`).join('');\n\n  $('out').hidden = false;\n  requestAnimationFrame(() => requestAnimationFrame(() => document.querySelectorAll('.fill').forEach(f => { f.style.width = Math.min(100, f.dataset.w) + '%'; })));\n}\n\n$('run').onclick = render;\n$('price').oninput = () => { if (!$('out').hidden) { render(); } };\n$('sample').onclick = () => { $('src').value = SAMPLE; render(); };\n$('file').onchange = e => { const f = e.target.files[0]; if (!f) { return; } const r = new FileReader(); r.onload = () => { $('src').value = r.result; render(); }; r.readAsText(f, 'utf-8'); };\n$('copy').onclick = () => navigator.clipboard.writeText($('sum').textContent).then(() => toast('요약을 복사했어요'), () => toast('복사하지 못했어요'));\n$('src').value = SAMPLE; render();\n</script>\n</body>\n</html>\n"},{"file":"copilot-readiness-check.html","Title":"Copilot 도입 준비도 진단","Summary":"18문항으로 6개 영역 준비도를 레이더 차트로","Category":"점검표","WorkArea":["고객 업무 이해하고 설계하기"],"Tools":["Claude","Copilot"],"Scope":["고객 프로젝트용"],"Does":"전략 · 데이터 보안 · 기술 · 시나리오 · 사람 · 측정 6개 영역을 18문항으로 진단해요\n답하는 대로 레이더 차트와 종합 점수가 바뀌어요\n가장 약한 영역 3개와 먼저 할 일을 추천해요","MakerNote":"첫 미팅에서 고객과 같이 눌러 보면 대화가 자연스럽게 다음 단계로 이어져요.","Output":"준비도 점수 · 레이더 차트 · 먼저 할 일 3개","rel":[["1.0","처음 공유",20]],"stars":5,"review":"첫 미팅 아이스브레이킹으로 최고예요. 고객이 점수를 보고 먼저 지원을 요청했어요","text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Copilot 도입 준비도 진단</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--warn:#c77a06;--bad:#cf3f3f;--area:rgba(10,108,189,.22);--stroke:#0a6cbd}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--warn:#f0a83a;--bad:#ff7a7a;--area:rgba(128,202,255,.25);--stroke:#80CAFF}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1120px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 22px}\n.layout{display:grid;grid-template-columns:1fr 400px;gap:16px;align-items:start}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 4px;display:flex;justify-content:space-between;align-items:center}\n.card h2 small{font-size:13px;color:var(--sub);font-weight:600}\n.desc{color:var(--sub);font-size:13px;margin:0 0 12px}\n.q{padding:10px 0;border-top:1px solid var(--line)}\n.q p{margin:0 0 8px;font-size:14px}\n.scale{display:flex;gap:6px}\n.scale button{flex:1;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:7px 0;font-weight:600;font-size:13px;font-family:inherit;cursor:pointer;transition:.15s}\n.scale button:hover{border-color:var(--stroke)}\n.scale button.on{background:var(--pri);color:var(--onpri);border-color:var(--pri)}\n.hint{display:flex;justify-content:space-between;font-size:11px;color:var(--sub);margin-top:4px}\n.side{position:sticky;top:16px}\n.score{text-align:center}\n.score .big{font-size:48px;font-weight:800;letter-spacing:-.03em}\n.score .lv{display:inline-block;padding:4px 12px;border-radius:999px;font-weight:700;font-size:13px}\nsvg text{fill:var(--sub);font-size:11px;font-family:inherit}\n.recs{margin:0;padding:0;list-style:none}\n.recs li{padding:10px 0;border-top:1px solid var(--line);font-size:14px}\n.recs b{display:block;margin-bottom:2px}\n.progress{height:6px;background:var(--soft);border-radius:999px;overflow:hidden;margin:10px 0 2px}\n.progress i{display:block;height:100%;background:var(--stroke);width:0;transition:width .3s}\n.row{display:flex;gap:8px;margin-top:12px}\nbutton.pri{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost{background:var(--soft);color:var(--ink)}\n@media (max-width:900px){.layout{grid-template-columns:1fr}.side{position:static}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Copilot 도입 준비도 진단</h1>\n  <p class=\"lead\">6개 영역 18개 질문에 답하면 조직의 Microsoft 365 Copilot 도입 준비도를 레이더 차트로 보여 주고, 먼저 할 일을 추천해요. 고객 워크숍에서 함께 눌러 보세요.</p>\n  <div class=\"layout\">\n    <div id=\"qs\"></div>\n    <div class=\"side\">\n      <div class=\"card score\">\n        <div class=\"desc\">종합 준비도</div>\n        <div class=\"big\" id=\"total\">–</div>\n        <div class=\"lv\" id=\"level\"></div>\n        <div class=\"progress\"><i id=\"prog\"></i></div>\n        <div class=\"desc\" id=\"answered\"></div>\n        <svg id=\"radar\" viewBox=\"0 0 360 330\" width=\"100%\"></svg>\n      </div>\n      <div class=\"card\"><h2>먼저 할 일</h2><ul class=\"recs\" id=\"recs\"><li>질문에 답하면 추천이 나와요.</li></ul>\n        <div class=\"row\"><button class=\"pri\" id=\"copy\">결과 복사</button><button class=\"pri ghost\" id=\"demo\">예시로 채우기</button><button class=\"pri ghost\" id=\"reset\">초기화</button></div>\n      </div>\n    </div>\n  </div>\n</div>\n<script>\nconst AREAS = [\n  { k: '전략·스폰서십', d: '경영진이 왜 도입하는지 분명히 말할 수 있나요?', q: ['경영진 스폰서가 정해져 있고 도입 목적을 공개적으로 말한다', '측정할 수 있는 도입 목표(예: 활성 사용률, 절감 시간)가 있다', '파일럿 대상 부서와 시나리오가 정해져 있다'],\n    rec: '경영진 스폰서와 함께 도입 목적 1문장과 측정 목표 3개를 정하세요.' },\n  { k: '데이터·보안', d: 'Copilot은 사용자가 접근할 수 있는 모든 자료를 참고해요.', q: ['SharePoint·Teams의 \"모든 사람\" 공유 현황을 점검했다', '민감도 레이블이 정의되어 있고 일부라도 적용 중이다', '소유자가 없거나 오래된 사이트를 정리하는 절차가 있다'],\n    rec: '데이터 과다 공유(오버셰어링) 점검부터 하세요. 민감한 사이트의 \"모든 사람\" 권한 제거가 1순위예요.' },\n  { k: '기술 환경', d: 'M365 앱과 라이선스가 준비되어 있나요?', q: ['대상자가 최신 Microsoft 365 앱(Teams, Outlook, Office)을 쓴다', '자료가 개인 PC가 아닌 OneDrive·SharePoint에 저장되어 있다', 'Copilot 라이선스 배정·회수 절차가 정해져 있다'],\n    rec: '파일을 OneDrive·SharePoint로 옮기는 캠페인을 먼저 하세요. 클라우드에 없는 자료는 Copilot이 못 봐요.' },\n  { k: '업무 시나리오', d: '어떤 일에 쓸지 구체적으로 정했나요?', q: ['부서별로 반복 업무와 소요 시간을 파악했다', 'Copilot을 쓸 우선 시나리오 3~5개를 골랐다', '시나리오별 예시 프롬프트가 준비되어 있다'],\n    rec: '부서별 반복 업무 목록을 받아 효과·난이도로 시나리오 우선순위를 정하세요.' },\n  { k: '사람·문화', d: '직원들이 새 도구를 받아들일 준비가 되어 있나요?', q: ['AI 도입에 대한 직원의 걱정(일자리, 감시)을 다룰 계획이 있다', '부서마다 챔피언(먼저 써 보고 알려 줄 사람)이 있다', '직무별 교육 계획과 질문할 채널이 있다'],\n    rec: '챔피언을 부서마다 1명씩 정하고, 걱정에 답하는 FAQ와 직무별 교육을 준비하세요.' },\n  { k: '측정·개선', d: '잘 되고 있는지 어떻게 알 수 있나요?', q: ['사용량 보고서를 정기적으로 확인할 담당자가 있다', '사용자 설문(만족도, 절감 시간)을 할 계획이 있다', '성공 사례를 모아 공유하는 방법이 있다'],\n    rec: '월 1회 사용 현황 보고와 분기 설문 일정을 먼저 정하세요. 측정하지 않으면 확산 근거가 없어요.' }\n];\nconst LABELS = ['전혀 아니다', '', '보통', '', '매우 그렇다'];\nconst ans = AREAS.map(a => a.q.map(() => 0));\nconst $ = id => document.getElementById(id);\n\n$('qs').innerHTML = AREAS.map((a, i) => `<div class=\"card\"><h2>${i + 1}. ${a.k}<small id=\"as${i}\">–</small></h2><p class=\"desc\">${a.d}</p>` +\n  a.q.map((q, j) => `<div class=\"q\"><p>${q}</p><div class=\"scale\" data-a=\"${i}\" data-q=\"${j}\">${[1, 2, 3, 4, 5].map(v => `<button data-v=\"${v}\">${v}</button>`).join('')}</div><div class=\"hint\"><span>전혀 아니다</span><span>매우 그렇다</span></div></div>`).join('') + '</div>').join('');\n\ndocument.querySelectorAll('.scale').forEach(s => s.addEventListener('click', e => {\n  const b = e.target.closest('button'); if (!b) { return; }\n  ans[s.dataset.a][s.dataset.q] = Number(b.dataset.v); update();\n}));\n\nfunction areaScore(i) { const v = ans[i].filter(Boolean); return v.length ? v.reduce((x, y) => x + y, 0) / v.length : 0; }\n\nfunction radar(scores) {\n  const cx = 180, cy = 165, R = 120, n = scores.length;\n  const pt = (i, r) => { const a = -Math.PI / 2 + i * 2 * Math.PI / n; return [cx + r * Math.cos(a), cy + r * Math.sin(a)]; };\n  let s = '';\n  for (let lv = 1; lv <= 5; lv++) { s += `<polygon points=\"${scores.map((_, i) => pt(i, R * lv / 5).join(',')).join(' ')}\" fill=\"none\" stroke=\"var(--line)\"/>`; }\n  scores.forEach((_, i) => { const [x, y] = pt(i, R); s += `<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x}\" y2=\"${y}\" stroke=\"var(--line)\"/>`; });\n  s += `<polygon points=\"${scores.map((v, i) => pt(i, R * v / 5).join(',')).join(' ')}\" fill=\"var(--area)\" stroke=\"var(--stroke)\" stroke-width=\"2\" style=\"transition:all .4s\"/>`;\n  scores.forEach((v, i) => { const [x, y] = pt(i, R * v / 5); if (v) { s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"4\" fill=\"var(--stroke)\"/>`; } });\n  AREAS.forEach((a, i) => { const [x, y] = pt(i, R + 22); s += `<text x=\"${x}\" y=\"${y + 4}\" text-anchor=\"middle\">${a.k}${scores[i] ? ' ' + scores[i].toFixed(1) : ''}</text>`; });\n  $('radar').innerHTML = s;\n}\n\nfunction update() {\n  document.querySelectorAll('.scale').forEach(s => s.querySelectorAll('button').forEach(b => b.classList.toggle('on', ans[s.dataset.a][s.dataset.q] === Number(b.dataset.v))));\n  const scores = AREAS.map((_, i) => areaScore(i));\n  scores.forEach((v, i) => { $('as' + i).textContent = v ? v.toFixed(1) + ' / 5' : '–'; });\n  const done = ans.flat().filter(Boolean).length, all = ans.flat().length;\n  $('prog').style.width = done / all * 100 + '%';\n  $('answered').textContent = `${done} / ${all} 문항 답함`;\n  radar(scores);\n  const valid = scores.filter(Boolean);\n  if (!valid.length) { $('total').textContent = '–'; $('level').textContent = ''; return; }\n  const t = Math.round(valid.reduce((a, b) => a + b, 0) / valid.length * 20);\n  $('total').textContent = t + '점';\n  const lv = t >= 80 ? ['확산 준비 완료', 'var(--ok)'] : t >= 60 ? ['파일럿 가능', 'var(--stroke)'] : t >= 40 ? ['기반 정비 필요', 'var(--warn)'] : ['준비 단계', 'var(--bad)'];\n  $('level').textContent = lv[0]; $('level').style.color = lv[1]; $('level').style.background = 'var(--soft)';\n  const weak = scores.map((v, i) => ({ v, i })).filter(x => x.v).sort((a, b) => a.v - b.v).slice(0, 3);\n  $('recs').innerHTML = weak.map((x, n) => `<li><b>${n + 1}. ${AREAS[x.i].k} (${x.v.toFixed(1)})</b>${AREAS[x.i].rec}</li>`).join('');\n}\n\n$('copy').onclick = () => {\n  const scores = AREAS.map((_, i) => areaScore(i));\n  const txt = `[Copilot 도입 준비도 진단] 종합 ${$('total').textContent} · ${$('level').textContent}\\n` + AREAS.map((a, i) => `- ${a.k}: ${scores[i] ? scores[i].toFixed(1) : '미응답'}`).join('\\n') +\n    '\\n\\n먼저 할 일\\n' + [...document.querySelectorAll('#recs li')].map(l => '- ' + l.innerText.replace('\\n', ': ')).join('\\n');\n  navigator.clipboard.writeText(txt);\n  $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '결과 복사'; }, 1500);\n};\n$('demo').onclick = () => { const d = [[5, 4, 4], [2, 2, 1], [4, 3, 3], [3, 2, 2], [3, 1, 2], [2, 2, 1]]; d.forEach((r, i) => r.forEach((v, j) => { ans[i][j] = v; })); update(); };\n$('reset').onclick = () => { ans.forEach(r => r.fill(0)); update(); };\nupdate();\n</script>\n</body>\n</html>\n"},{"file":"copilot-roi-calculator.html","Title":"Copilot 도입 효과(ROI) 계산기","Summary":"슬라이더를 움직이면 순효과 · 회수 기간 · 손익분기점이 바로","Category":"계산기","WorkArea":["제안과 전략 세우기"],"Tools":["Claude"],"Scope":["고객 프로젝트용"],"Does":"인원 · 절감 시간 · 활용률 · 인건비 · 라이선스 비용으로 연간 순효과를 계산해요\n12개월 누적 그래프에 손익분기 시점을 표시해요\n보수 · 기준 · 낙관 세 경우를 비교하고 계산 근거를 복사할 수 있어요","MakerNote":"\"그래서 얼마 아껴요?\" 질문에 고객 숫자로 그 자리에서 답하려고 만들었어요.","Output":"연간 순효과 · 투자 회수 기간 · 계산 근거","rel":[["1.0","처음 공유",16],["1.1","손익분기 활용률 추가",1]],"stars":4,"review":"경영진 미팅에서 활용률 슬라이더를 같이 움직여 보니 설득이 쉬웠어요","text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Copilot 도입 효과 계산기</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--bad:#cf3f3f;--c1:#0a6cbd;--c2:#9cc9ee;--c3:#cf3f3f}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--bad:#ff7a7a;--c1:#80CAFF;--c2:#35587a;--c3:#ff7a7a}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1120px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 22px}\n.layout{display:grid;grid-template-columns:360px 1fr;gap:16px;align-items:start}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 12px}\n.f{margin:14px 0}\n.f label{display:flex;justify-content:space-between;font-size:14px;margin-bottom:6px}\n.f label b{font-variant-numeric:tabular-nums}\n.f small{display:block;color:var(--sub);font-size:12px;margin-top:2px}\ninput[type=range]{width:100%;accent-color:var(--c1)}\ninput[type=number]{width:100%;padding:8px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit}\n.hero{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:16px}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px}\n.kpi .l{color:var(--sub);font-size:13px}\n.kpi .v{font-size:28px;font-weight:800;letter-spacing:-.02em;margin-top:4px;font-variant-numeric:tabular-nums}\n.kpi .d{font-size:13px;color:var(--sub)}\n.pos{color:var(--ok)}.neg{color:var(--bad)}\n.scen{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}\n.sc{border:1px solid var(--line);border-radius:12px;padding:14px;text-align:center}\n.sc.base{border-color:var(--c1);box-shadow:0 0 0 1px var(--c1) inset}\n.sc .t{font-size:13px;color:var(--sub)}\n.sc .n{font-size:20px;font-weight:800;margin:4px 0;font-variant-numeric:tabular-nums}\nsvg text{fill:var(--sub);font-size:11px;font-family:inherit}\n.legend{display:flex;gap:16px;font-size:12px;color:var(--sub);margin-top:6px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}\n.explain{font-size:13px;color:var(--sub);white-space:pre-wrap;background:var(--soft);border-radius:12px;padding:14px;margin:0}\nbutton{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri);margin-top:12px}\n@media (max-width:900px){.layout{grid-template-columns:1fr}.hero,.scen{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Copilot 도입 효과(ROI) 계산기</h1>\n  <p class=\"lead\">숫자를 움직이면 연간 절감액, 순효과, 투자 회수 기간이 바로 바뀌어요. 고객 미팅에서 고객의 숫자로 함께 계산해 보세요.</p>\n  <div class=\"layout\">\n    <div class=\"card\" id=\"inputs\"><h2>입력값</h2></div>\n    <div>\n      <div class=\"hero\">\n        <div class=\"kpi\"><div class=\"l\">연간 순효과</div><div class=\"v\" id=\"net\"></div><div class=\"d\" id=\"netd\"></div></div>\n        <div class=\"kpi\"><div class=\"l\">투자 회수 기간</div><div class=\"v\" id=\"pay\"></div><div class=\"d\">기준 시나리오</div></div>\n        <div class=\"kpi\"><div class=\"l\">연간 절감 시간</div><div class=\"v\" id=\"hrs\"></div><div class=\"d\" id=\"fte\"></div></div>\n      </div>\n      <div class=\"card\"><h2>12개월 누적 효과</h2><svg id=\"chart\" viewBox=\"0 0 640 240\" width=\"100%\"></svg>\n        <div class=\"legend\"><span><i style=\"background:var(--c1)\"></i>누적 절감액</span><span><i style=\"background:var(--c3)\"></i>누적 비용</span></div></div>\n      <div class=\"card\"><h2>세 가지 경우 비교</h2><div class=\"scen\" id=\"scen\"></div></div>\n      <div class=\"card\"><h2>계산 근거</h2><p class=\"explain\" id=\"explain\"></p><button id=\"copy\">근거 복사</button></div>\n    </div>\n  </div>\n</div>\n<script>\nconst F = [\n  { k: 'n', l: '대상 인원', u: '명', min: 10, max: 2000, step: 10, v: 300 },\n  { k: 'h', l: '1인 주당 절감 시간', u: '시간', min: 0.5, max: 10, step: 0.5, v: 2.5, s: '메일 정리, 회의 요약, 문서 초안 등 (Microsoft 조사 기준 주 1~4시간)' },\n  { k: 'r', l: '활용률 (기준)', u: '%', min: 10, max: 100, step: 5, v: 60, s: '라이선스 받은 사람 중 실제로 꾸준히 쓰는 비율' },\n  { k: 'w', l: '시간당 인건비', u: '원', min: 20000, max: 150000, step: 5000, v: 45000 },\n  { k: 'p', l: '1인 월 라이선스 비용', u: '원', min: 0, max: 100000, step: 1000, v: 44000, s: '실제 계약 단가로 바꿔 넣으세요' },\n  { k: 'c', l: '도입 비용 (교육·컨설팅·변화관리)', u: '원', min: 0, max: 500000000, step: 5000000, v: 60000000, num: true }\n];\nconst st = {}; F.forEach(f => { st[f.k] = f.v; });\nconst $ = id => document.getElementById(id);\nconst won = n => { const a = Math.abs(n); const s = n < 0 ? '−' : ''; return a >= 1e8 ? s + (a / 1e8).toFixed(1) + '억 원' : a >= 1e4 ? s + Math.round(a / 1e4).toLocaleString('ko-KR') + '만 원' : s + Math.round(a).toLocaleString('ko-KR') + '원'; };\nconst show = f => f.u === '원' ? Number(st[f.k]).toLocaleString('ko-KR') + '원' : st[f.k] + f.u;\n\n$('inputs').innerHTML += F.map(f => `<div class=\"f\"><label>${f.l}<b id=\"v_${f.k}\">${show(f)}</b></label>\n  <input type=\"${f.num ? 'number' : 'range'}\" id=\"i_${f.k}\" min=\"${f.min}\" max=\"${f.max}\" step=\"${f.step}\" value=\"${f.v}\">${f.s ? `<small>${f.s}</small>` : ''}</div>`).join('');\nF.forEach(f => { $('i_' + f.k).addEventListener('input', e => { st[f.k] = Number(e.target.value); $('v_' + f.k).textContent = show(f); calc(); }); });\n\nfunction model(rate) {\n  const hours = st.n * st.h * rate * 46;\n  const save = hours * st.w;\n  const cost = st.n * st.p * 12 + st.c;\n  return { hours, save, cost, net: save - cost, pay: save > 0 ? cost / (save / 12) : Infinity };\n}\n\nfunction chart(m) {\n  const W = 640, H = 240, l = 56, b = 28, t = 12, r = 12;\n  const months = [...Array(13).keys()];\n  const sv = months.map(i => m.save / 12 * i);\n  const cs = months.map(i => st.c + st.n * st.p * i);\n  const max = Math.max(...sv, ...cs) * 1.08 || 1;\n  const x = i => l + (W - l - r) * i / 12, y = v => H - b - (H - b - t) * v / max;\n  let s = '';\n  for (let g = 0; g <= 4; g++) { const v = max * g / 4; s += `<line x1=\"${l}\" x2=\"${W - r}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"var(--line)\"/><text x=\"${l - 6}\" y=\"${y(v) + 4}\" text-anchor=\"end\">${won(v).replace(' 원', '')}</text>`; }\n  months.forEach(i => { if (i % 2 === 0) { s += `<text x=\"${x(i)}\" y=\"${H - 8}\" text-anchor=\"middle\">${i}개월</text>`; } });\n  const line = (arr, c) => `<polyline points=\"${arr.map((v, i) => x(i) + ',' + y(v)).join(' ')}\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>`;\n  s += `<polygon points=\"${x(0)},${y(0)} ${sv.map((v, i) => x(i) + ',' + y(v)).join(' ')} ${x(12)},${y(0)}\" fill=\"var(--c1)\" opacity=\".1\"/>`;\n  s += line(cs, 'var(--c3)') + line(sv, 'var(--c1)');\n  if (m.pay <= 12) {\n    const pm = m.pay, vx = x(pm), vy = y(m.save / 12 * pm);\n    s += `<line x1=\"${vx}\" x2=\"${vx}\" y1=\"${t}\" y2=\"${H - b}\" stroke=\"var(--ok)\" stroke-dasharray=\"4 4\"/><circle cx=\"${vx}\" cy=\"${vy}\" r=\"5\" fill=\"var(--ok)\"/><text x=\"${vx + 8}\" y=\"${t + 12}\" style=\"fill:var(--ok);font-weight:700\">손익분기 ${pm.toFixed(1)}개월</text>`;\n  }\n  $('chart').innerHTML = s;\n}\n\nfunction calc() {\n  const base = model(st.r / 100);\n  $('net').textContent = won(base.net); $('net').className = 'v ' + (base.net >= 0 ? 'pos' : 'neg');\n  $('netd').textContent = `절감 ${won(base.save)} − 비용 ${won(base.cost)}`;\n  $('pay').textContent = isFinite(base.pay) ? base.pay.toFixed(1) + '개월' : '회수 안 됨';\n  $('hrs').textContent = Math.round(base.hours).toLocaleString('ko-KR') + '시간';\n  $('fte').textContent = `정규직 약 ${(base.hours / 1840).toFixed(1)}명 분량`;\n  const cases = [['보수', Math.max(0.1, st.r / 100 - 0.2)], ['기준', st.r / 100], ['낙관', Math.min(1, st.r / 100 + 0.2)]];\n  $('scen').innerHTML = cases.map(([n, r], i) => { const m = model(r); return `<div class=\"sc ${i === 1 ? 'base' : ''}\"><div class=\"t\">${n} · 활용률 ${Math.round(r * 100)}%</div><div class=\"n ${m.net >= 0 ? 'pos' : 'neg'}\">${won(m.net)}</div><div class=\"t\">회수 ${isFinite(m.pay) ? m.pay.toFixed(1) + '개월' : '안 됨'}</div></div>`; }).join('');\n  const be = (st.n * st.p * 12 + st.c) / (st.n * st.h * 46 * st.w);\n  $('explain').textContent =\n`연간 절감 시간 = ${st.n}명 × 주 ${st.h}시간 × 활용률 ${st.r}% × 46주 = ${Math.round(base.hours).toLocaleString('ko-KR')}시간\n연간 절감액 = ${Math.round(base.hours).toLocaleString('ko-KR')}시간 × ${st.w.toLocaleString('ko-KR')}원 = ${won(base.save)}\n연간 비용 = ${st.n}명 × ${st.p.toLocaleString('ko-KR')}원 × 12개월 + 도입 비용 ${won(st.c)} = ${won(base.cost)}\n순효과 = ${won(base.net)} · 투자 회수 ${isFinite(base.pay) ? base.pay.toFixed(1) + '개월' : '안 됨'}\n손익분기 활용률 = ${(be * 100).toFixed(1)}% — 이보다 많이 쓰면 이익이에요.`;\n  chart(base);\n}\n$('copy').onclick = () => { navigator.clipboard.writeText($('explain').textContent); $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '근거 복사'; }, 1500); };\ncalc();\n</script>\n</body>\n</html>\n"},{"file":"agent-tool-picker.html","Title":"Agent 도구 선택 도우미","Summary":"질문 7개로 Copilot · Agent Builder · Copilot Studio 중 추천","Category":"판단 도우미","WorkArea":["고객 업무 이해하고 설계하기"],"Tools":["Claude","ChatGPT"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"사용자 · 지식 · 실행 · 배포 · 라이선스 · 일정 · 관리자 7개 질문에 답하면 도구를 추천해요\n추천 이유와 다음에 할 일 3단계를 보여 줘요\n세 도구를 한눈에 비교하는 표가 같이 나와요","MakerNote":"고객이 \"이건 Copilot Studio로 해야 해요?\"라고 물을 때마다 같은 설명을 반복해서 만들었어요.","Output":"추천 도구 · 판단 이유 · 비교표","rel":[["1.0","처음 공유",12]],"stars":4,"text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Agent 도구 선택 도우미</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--c1:#0a6cbd;--c2:#7b5cd6;--c3:#d9822b}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--c1:#80CAFF;--c2:#b8a4ff;--c3:#ffb46b}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:860px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 22px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:24px;margin-bottom:16px}\n.steps{display:flex;gap:6px;margin-bottom:18px}\n.steps i{flex:1;height:5px;border-radius:999px;background:var(--soft);transition:.3s}\n.steps i.on{background:var(--c1)}\n.qn{color:var(--sub);font-size:13px;font-weight:700}\n.qt{font-size:21px;font-weight:800;margin:4px 0 6px;letter-spacing:-.01em}\n.qd{color:var(--sub);font-size:14px;margin:0 0 18px}\n.opts{display:grid;gap:10px}\n.opt{text-align:left;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:12px;padding:14px 16px;font:inherit;cursor:pointer;transition:.15s}\n.opt:hover{border-color:var(--c1);transform:translateX(3px)}\n.opt b{display:block}\n.opt span{color:var(--sub);font-size:13px}\n.nav{display:flex;justify-content:space-between;margin-top:16px}\nbutton.link{border:0;background:none;color:var(--sub);font:inherit;cursor:pointer;padding:0}\n.res-top{display:flex;gap:16px;align-items:center}\n.medal{width:64px;height:64px;border-radius:18px;display:grid;place-items:center;font-size:28px;color:#fff;flex:none}\n.res-top h2{margin:0;font-size:24px}\n.res-top p{margin:2px 0 0;color:var(--sub)}\n.meter{margin:18px 0}\n.meter .m{display:grid;grid-template-columns:130px 1fr 44px;gap:10px;align-items:center;margin:8px 0;font-size:14px}\n.meter .t{height:12px;background:var(--soft);border-radius:999px;overflow:hidden}\n.meter .t i{display:block;height:100%;border-radius:999px;width:0;transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.meter .p{text-align:right;font-variant-numeric:tabular-nums;color:var(--sub)}\nh3{font-size:15px;margin:18px 0 8px}\nul{margin:0;padding-left:20px}\nli{margin:4px 0}\n.why li{color:var(--ink)}\n.cmp{width:100%;border-collapse:collapse;font-size:13px;margin-top:6px}\n.cmp th,.cmp td{padding:8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}\n.cmp th{color:var(--sub);font-weight:600}\n.cmp td.hl{background:var(--soft);font-weight:600}\nbutton.pri{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Agent 도구 선택 도우미</h1>\n  <p class=\"lead\">만들고 싶은 Agent에 대해 7개 질문에 답하면 <b>Copilot 채팅 + 프롬프트</b>, <b>Agent Builder</b>, <b>Copilot Studio</b> 중 무엇이 맞는지 이유와 함께 알려 드려요.</p>\n  <div class=\"card\" id=\"box\"></div>\n</div>\n<script>\nconst TOOLS = {\n  chat: { n: 'Copilot 채팅 + 프롬프트', c: 'var(--c3)', i: '💬', d: 'Agent를 만들 필요 없이 저장한 프롬프트로 충분해요.',\n    next: ['자주 쓰는 프롬프트를 Copilot 프롬프트 갤러리에 저장하세요', '팀에 공유해 같은 결과를 내게 하세요', '반복이 늘면 Agent Builder로 옮기세요'] },\n  builder: { n: 'Agent Builder', c: 'var(--c1)', i: '🧩', d: 'Microsoft 365 Copilot 안에서 코드 없이 몇 분 만에 만드는 Agent예요.',\n    next: ['Copilot 앱 → Agent 만들기에서 지침을 자연어로 쓰세요', 'SharePoint 사이트·파일을 지식으로 연결하세요', '팀원에게 공유하고 1주일 써 본 뒤 지침을 다듬으세요'] },\n  studio: { n: 'Copilot Studio', c: 'var(--c2)', i: '🛠️', d: '외부 시스템 연결, 업무 흐름 자동화, 여러 채널 배포가 필요한 Agent예요.',\n    next: ['Copilot Studio에서 환경과 데이터 손실 방지(DLP) 정책을 확인하세요', '커넥터·Power Automate 흐름을 설계하세요', '테스트 → 승인 → 게시 절차를 IT와 정하세요'] }\n};\nconst Q = [\n  { t: '이 Agent는 누가 쓰나요?', d: '사용 범위가 넓을수록 관리 기능이 필요해요.', o: [\n    ['나 혼자', '내 업무를 빠르게 처리', { chat: 3, builder: 1 }, '혼자 쓰는 용도라 가볍게 시작할 수 있어요'],\n    ['우리 팀', '팀원 5~30명이 함께', { builder: 3, studio: 1 }, '팀 공유는 Agent Builder로 충분해요'],\n    ['전사 또는 고객', '부서 밖, 외부 사용자까지', { studio: 3 }, '전사·외부 배포는 Copilot Studio의 관리·배포 기능이 필요해요']] },\n  { t: '어떤 자료를 근거로 답하나요?', d: 'Agent가 참고할 지식의 위치예요.', o: [\n    ['내가 대화에 붙여 넣는 내용', '그때그때 다름', { chat: 3 }, '매번 자료가 달라 프롬프트로 충분해요'],\n    ['SharePoint·OneDrive 문서', '사내 규정, 매뉴얼, 양식', { builder: 3, studio: 1 }, 'SharePoint 문서는 Agent Builder에서 바로 연결돼요'],\n    ['외부 시스템 데이터', 'ERP, CRM, DB, 웹 API', { studio: 3 }, '외부 시스템 데이터는 Copilot Studio 커넥터가 필요해요']] },\n  { t: '답하는 것 말고 \"실행\"도 해야 하나요?', d: '예: 티켓 생성, 승인 요청, 메일 발송', o: [\n    ['아니요, 답만 하면 돼요', '질문과 답변', { chat: 2, builder: 2 }, '답변만 하면 되니 단순한 도구로 충분해요'],\n    ['간단한 작업 한두 개', '예: 일정 만들기', { builder: 1, studio: 2 }, '작업이 있으면 Copilot Studio가 더 안정적이에요'],\n    ['여러 단계 업무 흐름', '예: 접수 → 검토 → 승인 → 알림', { studio: 4 }, '여러 단계 자동화는 Copilot Studio + Power Automate가 맞아요']] },\n  { t: '어디에서 쓰나요?', d: '사용자가 Agent를 만나는 곳이에요.', o: [\n    ['Microsoft 365 Copilot 안에서', 'Copilot 앱, Teams 채팅', { chat: 1, builder: 3 }, 'M365 Copilot 안에서 쓰면 Agent Builder가 가장 빨라요'],\n    ['Teams 채널·웹사이트에도', '여러 채널에 배포', { studio: 3 }, '여러 채널 배포는 Copilot Studio만 할 수 있어요']] },\n  { t: '사용자에게 Copilot 라이선스가 있나요?', d: '라이선스에 따라 쓸 수 있는 방법이 달라요.', o: [\n    ['모두 있어요', 'Microsoft 365 Copilot', { chat: 1, builder: 2 }, '라이선스가 있으면 Agent Builder를 추가 비용 없이 쓸 수 있어요'],\n    ['일부만 있거나 없어요', '외부 사용자 포함', { studio: 3 }, '라이선스가 없는 사용자에게는 Copilot Studio로 배포해야 해요']] },\n  { t: '얼마나 빨리 필요해요?', d: '만드는 데 드는 시간이에요.', o: [\n    ['오늘 바로', '몇 분 ~ 1시간', { chat: 2, builder: 2 }, '오늘 바로 써야 하면 코드 없는 방법이 좋아요'],\n    ['1~2주 안에', '테스트 포함', { builder: 2, studio: 1 }, ''],\n    ['한 달 이상 프로젝트', '설계·승인 포함', { studio: 2 }, '프로젝트 단위라면 Copilot Studio로 제대로 설계할 수 있어요']] },\n  { t: '누가 만들고 관리하나요?', d: '만든 뒤 유지보수까지 생각해 보세요.', o: [\n    ['현업 담당자', '코딩 경험 없음', { chat: 1, builder: 3 }, '현업이 직접 고치려면 Agent Builder가 쉬워요'],\n    ['IT·개발 담당자', 'Power Platform 경험 있음', { studio: 3 }, 'IT 팀이 관리하면 Copilot Studio의 버전·환경 관리를 쓸 수 있어요']] }\n];\nlet step = 0; const pick = [];\nconst box = document.getElementById('box');\nfunction bar() { return `<div class=\"steps\">${Q.map((_, i) => `<i class=\"${i < step || (step === Q.length) ? 'on' : ''}\"></i>`).join('')}</div>`; }\nfunction ask() {\n  const q = Q[step];\n  box.innerHTML = bar() + `<div class=\"qn\">질문 ${step + 1} / ${Q.length}</div><div class=\"qt\">${q.t}</div><p class=\"qd\">${q.d}</p>\n    <div class=\"opts\">${q.o.map((o, i) => `<button class=\"opt\" data-i=\"${i}\"><b>${o[0]}</b><span>${o[1]}</span></button>`).join('')}</div>\n    <div class=\"nav\"><button class=\"link\" id=\"back\" ${step ? '' : 'hidden'}>← 이전 질문</button><span></span></div>`;\n  box.querySelectorAll('.opt').forEach(b => b.onclick = () => { pick[step] = Number(b.dataset.i); step++; step < Q.length ? ask() : result(); });\n  const back = document.getElementById('back'); if (back) { back.onclick = () => { step--; ask(); }; }\n}\nfunction result() {\n  const sc = { chat: 0, builder: 0, studio: 0 };\n  const why = { chat: [], builder: [], studio: [] };\n  pick.forEach((p, i) => { const o = Q[i].o[p]; Object.entries(o[2]).forEach(([k, v]) => { sc[k] += v; if (o[3] && v >= 2) { why[k].push(o[3]); } }); });\n  const tot = sc.chat + sc.builder + sc.studio || 1;\n  const order = Object.keys(sc).sort((a, b) => sc[b] - sc[a]);\n  const w = order[0], T = TOOLS[w];\n  box.innerHTML = bar() + `<div class=\"res-top\"><div class=\"medal\" style=\"background:${T.c}\">${T.i}</div><div><div class=\"qn\">추천 도구</div><h2>${T.n}</h2><p>${T.d}</p></div></div>\n    <div class=\"meter\">${order.map(k => `<div class=\"m\"><span>${TOOLS[k].n}</span><div class=\"t\"><i style=\"background:${TOOLS[k].c}\" data-w=\"${sc[k] / tot * 100}\"></i></div><span class=\"p\">${Math.round(sc[k] / tot * 100)}%</span></div>`).join('')}</div>\n    <h3>이렇게 판단했어요</h3><ul class=\"why\">${(why[w].length ? why[w] : ['답변을 종합하면 가장 잘 맞아요']).map(x => `<li>${x}</li>`).join('')}</ul>\n    <h3>다음에 할 일</h3><ol>${T.next.map(x => `<li>${x}</li>`).join('')}</ol>\n    <h3>한눈에 비교</h3>\n    <table class=\"cmp\"><tr><th></th>${['chat', 'builder', 'studio'].map(k => `<th>${TOOLS[k].n}</th>`).join('')}</tr>\n      ${[['만드는 시간', '몇 분', '몇 분 ~ 몇 시간', '며칠 ~ 몇 주'], ['지식', '대화에 붙인 자료', 'SharePoint·파일·웹', '외부 시스템 포함 모든 자료'], ['실행(작업)', '없음', '제한적', '커넥터·흐름으로 자유롭게'], ['배포', '개인', '팀·조직 공유', 'Teams·웹·여러 채널'], ['만드는 사람', '누구나', '현업 담당자', 'IT·메이커']]\n        .map(r => `<tr><td>${r[0]}</td>${[1, 2, 3].map(i => `<td class=\"${['chat', 'builder', 'studio'][i - 1] === w ? 'hl' : ''}\">${r[i]}</td>`).join('')}</tr>`).join('')}</table>\n    <div class=\"nav\"><button class=\"link\" id=\"back\">← 마지막 질문으로</button><button class=\"pri\" id=\"again\">처음부터 다시</button></div>`;\n  requestAnimationFrame(() => requestAnimationFrame(() => box.querySelectorAll('.meter i').forEach(i => { i.style.width = i.dataset.w + '%'; })));\n  document.getElementById('again').onclick = () => { step = 0; pick.length = 0; ask(); };\n  document.getElementById('back').onclick = () => { step = Q.length - 1; ask(); };\n}\nask();\n</script>\n</body>\n</html>\n"},{"file":"scenario-priority-matrix.html","Title":"시나리오 우선순위 매트릭스","Summary":"시나리오를 끌어다 놓으면 Quick Win부터 실행 순서가 정리돼요","Category":"판단 도우미","WorkArea":["제안과 전략 세우기"],"Tools":["Claude"],"Scope":["고객 프로젝트용"],"Does":"워크숍에서 나온 시나리오를 효과 × 난이도 2×2 판에 끌어다 놓아요\n빠른 성과 · 전략 과제 · 작은 개선 · 보류로 자동 분류하고 점수를 매겨요\n결과를 표로 복사해 Excel · Teams에 붙여 넣을 수 있어요","MakerNote":"워크숍 화이트보드 사진을 정리하는 시간이 아까워서 화면에서 바로 하도록 만들었어요.","Output":"시나리오 실행 순서표","rel":[["1.0","처음 공유",9]],"stars":5,"review":"고객 워크숍에서 화면 공유하고 같이 옮겼더니 결정이 10분 만에 끝났어요","text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>시나리오 우선순위 매트릭스</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--q1:#e3f5ec;--q2:#e6f0fb;--q3:#fff4e0;--q4:#f3f4f6;--k1:#1a8f63;--k2:#0a6cbd;--k3:#c77a06;--k4:#7a8796}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--q1:#11302a;--q2:#13283f;--q3:#33280f;--q4:#1a2330;--k1:#45c492;--k2:#80CAFF;--k3:#f0a83a;--k4:#9cafc3}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1160px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 20px}\n.layout{display:grid;grid-template-columns:1fr 340px;gap:16px;align-items:start}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 12px}\n.board{position:relative;display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;aspect-ratio:4/3;border-radius:12px;overflow:hidden;user-select:none;margin-left:22px;margin-bottom:22px}\n.qd{padding:12px;font-weight:800;font-size:14px}\n.qd small{display:block;font-weight:500;color:var(--sub);font-size:12px}\n.qd.a{background:var(--q2);color:var(--k2)}.qd.b{background:var(--q1);color:var(--k1)}.qd.c{background:var(--q4);color:var(--k4)}.qd.d{background:var(--q3);color:var(--k3)}\n.ax{position:absolute;color:var(--sub);font-size:12px;font-weight:700}\n.ax.y{left:-22px;top:50%;transform:translate(-50%,-50%) rotate(-90deg);white-space:nowrap;margin-left:-4px}\n.ax.x{bottom:-22px;left:50%;transform:translateX(-50%)}\n.boardwrap{position:relative}\n.chip{position:absolute;transform:translate(-50%,-50%);background:var(--card);border:2px solid var(--line);border-radius:999px;padding:5px 12px;font-size:13px;font-weight:600;cursor:grab;white-space:nowrap;box-shadow:0 3px 10px rgba(0,0,0,.12);transition:border-color .2s,box-shadow .2s;touch-action:none;max-width:200px;overflow:hidden;text-overflow:ellipsis}\n.chip:active{cursor:grabbing;box-shadow:0 8px 22px rgba(0,0,0,.2)}\n.chip.k1{border-color:var(--k1)}.chip.k2{border-color:var(--k2)}.chip.k3{border-color:var(--k3)}.chip.k4{border-color:var(--k4)}\n.add{display:flex;gap:8px}\n.add input{flex:1;padding:9px 12px;border:1px solid var(--line);border-radius:10px;background:var(--bg);color:var(--ink);font:inherit}\nbutton{border:0;border-radius:999px;padding:9px 16px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost{background:var(--soft);color:var(--ink)}\n.grp h3{font-size:14px;margin:14px 0 6px;display:flex;align-items:center;gap:8px}\n.grp h3 i{width:10px;height:10px;border-radius:50%;display:inline-block}\n.grp ol{margin:0;padding-left:20px;font-size:14px}\n.grp li{margin:3px 0}\n.grp li button{background:none;color:var(--sub);padding:0 4px;font-size:12px}\n.empty{color:var(--sub);font-size:13px}\n.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.tip{font-size:12px;color:var(--sub);margin-top:8px}\n@media (max-width:900px){.layout{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Copilot 시나리오 우선순위 매트릭스</h1>\n  <p class=\"lead\">고객 워크숍에서 나온 시나리오를 올리고, 효과와 실행 난이도에 맞게 끌어다 놓으세요. 오른쪽에 실행 순서가 바로 정리돼요.</p>\n  <div class=\"layout\">\n    <div class=\"card\">\n      <div class=\"add\"><input id=\"name\" placeholder=\"시나리오 이름 (예: 회의록 요약)\" maxlength=\"40\"><button id=\"addBtn\">올리기</button></div>\n      <p class=\"tip\">칩을 끌어서 옮기고, 두 번 누르면 지워요. 위쪽일수록 효과가 크고, 왼쪽일수록 쉬워요.</p>\n      <div class=\"boardwrap\">\n        <div class=\"board\" id=\"board\">\n          <div class=\"qd b\">빠른 성과 (Quick Win)<small>효과 크고 쉬움 → 지금 바로 파일럿</small></div>\n          <div class=\"qd a\">전략 과제<small>효과 크고 어려움 → 계획 세워 추진</small></div>\n          <div class=\"qd c\">작은 개선<small>효과 작고 쉬움 → 교육 때 팁으로</small></div>\n          <div class=\"qd d\">보류<small>효과 작고 어려움 → 다음에 다시 검토</small></div>\n          <span class=\"ax y\">효과 ↑</span><span class=\"ax x\">실행 난이도 →</span>\n        </div>\n      </div>\n    </div>\n    <div>\n      <div class=\"card grp\" id=\"groups\"></div>\n      <div class=\"card\"><h2>내보내기</h2><div class=\"row\"><button id=\"copy\">표로 복사</button><button class=\"ghost\" id=\"sample\">예시 시나리오</button><button class=\"ghost\" id=\"clear\">모두 지우기</button></div><p class=\"tip\">표로 복사하면 Excel·Word·Teams에 그대로 붙여 넣을 수 있어요.</p></div>\n    </div>\n  </div>\n</div>\n<script>\nconst $ = id => document.getElementById(id);\nconst KEY = 'scenario-matrix-v1';\nlet items = [];\ntry { items = JSON.parse(localStorage.getItem(KEY) || '[]'); } catch (e) { items = []; }\nconst SAMPLE = [['회의록 요약·할 일 정리', .2, .15], ['메일 답장 초안', .15, .3], ['제안서 초안 작성', .6, .17], ['고객 문의 자동 답변 Agent', .76, .31], ['주간 보고 취합', .35, .3],\n  ['엑셀 데이터 분석', .4, .45], ['사내 규정 Q&A', .45, .25], ['계약서 위험 조항 검토', .74, .64], ['슬라이드 디자인 정리', .3, .7], ['ERP 연동 발주 자동화', .8, .82]];\nconst save = () => { try { localStorage.setItem(KEY, JSON.stringify(items)); } catch (e) { /* 저장 못 해도 계속 써요 */ } };\nconst quad = it => it.y < .5 ? (it.x < .5 ? 1 : 2) : (it.x < .5 ? 3 : 4);\nconst META = { 1: ['빠른 성과 (Quick Win)', 'k1', '1~2주 안에 파일럿'], 2: ['전략 과제', 'k2', '분기 계획에 포함'], 3: ['작은 개선', 'k3', '교육 자료에 팁으로'], 4: ['보류', 'k4', '다음 분기 재검토'] };\nconst cls = q => ({ 1: 'k1', 2: 'k2', 3: 'k3', 4: 'k4' }[q]);\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nconst score = it => Math.round(((1 - it.y) * 2 + (1 - it.x)) / 3 * 100);\n\nfunction draw() {\n  const b = $('board');\n  b.querySelectorAll('.chip').forEach(c => c.remove());\n  items.forEach((it, i) => {\n    const c = document.createElement('div');\n    c.className = 'chip ' + cls(quad(it)); c.textContent = it.n; c.title = it.n;\n    c.style.left = it.x * 100 + '%'; c.style.top = it.y * 100 + '%';\n    c.onpointerdown = e => {\n      c.setPointerCapture(e.pointerId);\n      const r = b.getBoundingClientRect();\n      c.onpointermove = m => {\n        it.x = Math.min(.97, Math.max(.03, (m.clientX - r.left) / r.width));\n        it.y = Math.min(.96, Math.max(.04, (m.clientY - r.top) / r.height));\n        c.style.left = it.x * 100 + '%'; c.style.top = it.y * 100 + '%'; c.className = 'chip ' + cls(quad(it));\n      };\n      c.onpointerup = () => { c.onpointermove = null; save(); list(); };\n    };\n    c.ondblclick = () => { items.splice(i, 1); save(); draw(); };\n    b.appendChild(c);\n  });\n  list();\n}\nfunction list() {\n  $('groups').innerHTML = '<h2>실행 순서</h2>' + [1, 2, 3, 4].map(q => {\n    const g = items.filter(it => quad(it) === q).sort((a, b) => score(b) - score(a));\n    return `<h3><i style=\"background:var(--${META[q][1]})\"></i>${META[q][0]} <span class=\"empty\">· ${META[q][2]}</span></h3>` +\n      (g.length ? `<ol>${g.map(it => `<li>${esc(it.n)} <span class=\"empty\">${score(it)}점</span></li>`).join('')}</ol>` : '<div class=\"empty\">아직 없어요</div>');\n  }).join('');\n}\nfunction add() {\n  const n = $('name').value.trim(); if (!n) { return; }\n  items.push({ n, x: .5 + (Math.random() - .5) * .1, y: .5 + (Math.random() - .5) * .1 });\n  $('name').value = ''; save(); draw();\n}\n$('addBtn').onclick = add;\n$('name').onkeydown = e => { if (e.key === 'Enter') { add(); } };\n$('sample').onclick = () => { items = SAMPLE.map(([n, x, y]) => ({ n, x, y })); save(); draw(); };\n$('clear').onclick = () => { if (confirm('시나리오를 모두 지울까요?')) { items = []; save(); draw(); } };\n$('copy').onclick = () => {\n  const rows = [...items].sort((a, b) => quad(a) - quad(b) || score(b) - score(a)).map((it, i) => [i + 1, it.n, META[quad(it)][0], score(it), META[quad(it)][2]].join('\\t'));\n  navigator.clipboard.writeText(['순위\\t시나리오\\t구분\\t점수\\t다음 단계', ...rows].join('\\n'));\n  $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '표로 복사'; }, 1500);\n};\nif (!items.length) { items = SAMPLE.map(([n, x, y]) => ({ n, x, y })); }\ndraw();\n</script>\n</body>\n</html>\n"},{"file":"adkar-change-survey.html","Title":"ADKAR 변화 준비도 진단","Summary":"직원이 어느 단계에서 막혔는지 찾고 바로 할 일을 추천해요","Category":"투표 및 설문","WorkArea":["교육·확산 프로그램 운영하기"],"Tools":["Claude","Copilot"],"Scope":["고객 프로젝트용"],"Does":"ADKAR 5단계 10문항으로 개인의 변화 준비도를 진단해요\n그룹별 평균을 넣어 부서끼리 비교할 수 있어요\n3점 미만인 첫 단계를 \"막힌 지점\"으로 찾아 맞는 활동을 추천해요","MakerNote":"확산이 멈춘 부서가 왜 멈췄는지 설명할 근거가 필요해서 만들었어요.","Output":"단계별 점수 · 막힌 지점 · 추천 활동","rel":[["1.0","처음 공유",4]],"text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>ADKAR 변화 준비도 설문</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--warn:#c77a06;--bad:#cf3f3f;--c1:#0a6cbd}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--warn:#f0a83a;--bad:#ff7a7a;--c1:#80CAFF}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1000px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 20px}\n.tabs{display:flex;gap:6px;margin-bottom:16px;flex-wrap:wrap}\n.tabs button{border:1px solid var(--line);background:var(--card);color:var(--ink);border-radius:999px;padding:8px 16px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer}\n.tabs button.on{background:var(--pri);color:var(--onpri);border-color:var(--pri)}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 12px}\n.stage{display:grid;grid-template-columns:150px 1fr;gap:16px;padding:14px 0;border-top:1px solid var(--line)}\n.stage:first-of-type{border-top:0}\n.stage .nm b{display:block;font-size:15px}\n.stage .nm span{font-size:12px;color:var(--sub)}\n.sq p{margin:0 0 6px;font-size:14px}\n.sq + .sq{margin-top:12px}\n.scale{display:flex;gap:6px}\n.scale button{flex:1;border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:8px;padding:6px 0;font-weight:600;font-size:13px;font-family:inherit;cursor:pointer}\n.scale button.on{background:var(--pri);color:var(--onpri);border-color:var(--pri)}\n.groups{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}\n.g{border:1px solid var(--line);border-radius:12px;padding:12px}\n.g label{font-size:13px;color:var(--sub)}\n.g input{width:100%;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit;margin:4px 0 8px}\n.g .sl{display:grid;grid-template-columns:24px 1fr 28px;gap:6px;align-items:center;font-size:12px}\n.g .sl input{margin:0;padding:0;accent-color:var(--c1)}\n.chart{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;align-items:end;height:220px;padding:0 4px;border-bottom:1px solid var(--line);position:relative}\n.col{display:flex;flex-direction:column;justify-content:flex-end;align-items:center;height:100%}\n.col .v{font-weight:800;font-size:15px;margin-bottom:4px;font-variant-numeric:tabular-nums}\n.col .b{width:100%;max-width:90px;border-radius:10px 10px 0 0;background:var(--c1);transition:height .6s cubic-bezier(.2,.8,.2,1),background .3s}\n.col .b.barrier{background:var(--bad)}\n.col .b.weak{background:var(--warn)}\n.labels{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;text-align:center;font-size:13px;margin-top:8px}\n.labels span small{display:block;color:var(--sub);font-size:11px}\n.line3{position:absolute;left:0;right:0;border-top:2px dashed var(--sub);opacity:.4}\n.line3 span{position:absolute;right:0;top:-18px;font-size:11px;color:var(--sub)}\n.verdict{display:flex;gap:16px;align-items:flex-start;background:var(--soft);border-radius:12px;padding:16px;margin-top:18px}\n.verdict .ic{font-size:30px}\n.verdict h3{margin:0 0 4px;font-size:17px}\n.verdict ul{margin:6px 0 0;padding-left:18px;font-size:14px}\nbutton.pri{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\n.row{display:flex;gap:8px;margin-top:14px}\n.hint{font-size:12px;color:var(--sub)}\n@media (max-width:700px){.stage{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>ADKAR 변화 준비도 진단</h1>\n  <p class=\"lead\">Copilot 도입에서 직원들이 어느 단계에서 막혀 있는지 찾아요. ADKAR 모델은 <b>앞 단계가 3점 미만이면 그 단계가 \"막힌 지점\"</b>이라고 봐요. 막힌 지점부터 풀어야 다음 단계가 움직여요.</p>\n  <div class=\"tabs\"><button class=\"on\" data-m=\"one\">개인 설문</button><button data-m=\"team\">그룹 결과 입력</button></div>\n\n  <div class=\"card\" id=\"one\"></div>\n  <div class=\"card\" id=\"team\" hidden><h2>그룹별 평균 점수 입력</h2><p class=\"hint\">설문 결과의 단계별 평균(1~5)을 그룹마다 넣으면 그룹을 비교해 볼 수 있어요.</p><div class=\"groups\" id=\"groups\"></div></div>\n\n  <div class=\"card\">\n    <h2 id=\"rtitle\">결과</h2>\n    <div class=\"chart\" id=\"chart\"><div class=\"line3\" id=\"l3\"><span>3점 (막힘 기준)</span></div></div>\n    <div class=\"labels\" id=\"labels\"></div>\n    <div class=\"verdict\" id=\"verdict\"></div>\n    <div class=\"row\"><button class=\"pri\" id=\"copy\">결과 복사</button></div>\n  </div>\n</div>\n<script>\nconst S = [\n  { k: 'A', n: '인식', e: 'Awareness', q: ['회사가 왜 Copilot을 도입하는지 설명할 수 있다', '도입하지 않으면 어떤 문제가 생기는지 안다'],\n    act: ['경영진이 직접 도입 이유를 말하는 타운홀·영상 메시지', '팀장이 팀 회의에서 \"왜\"를 2분 동안 설명', '경쟁사·업계 변화 사례 공유'] },\n  { k: 'D', n: '의지', e: 'Desire', q: ['Copilot이 내 일을 편하게 해 줄 것 같다', '직접 써 보고 싶다'],\n    act: ['\"내 업무에서 아낀 시간\" 동료 사례 공유', '일자리·감시 걱정에 답하는 FAQ', '챔피언이 팀에서 직접 시연'] },\n  { k: 'K', n: '지식', e: 'Knowledge', q: ['Copilot을 어디서 어떻게 시작하는지 안다', '좋은 프롬프트를 쓰는 방법을 안다'],\n    act: ['직무별 1시간 실습 교육', '복사해 쓰는 프롬프트 모음 배포', '질문 채널(Teams) 열기'] },\n  { k: 'A', n: '실행력', e: 'Ability', q: ['내 실제 업무에 Copilot을 써 봤다', '막히면 스스로 해결하거나 도움을 받을 수 있다'],\n    act: ['\"매일 한 번 쓰기\" 2주 미션', '부서별 오피스 아워(질문 받는 시간)', '업무 맞춤 프롬프트를 챔피언과 같이 만들기'] },\n  { k: 'R', n: '정착', e: 'Reinforcement', q: ['Copilot 사용이 이제 습관이 됐다', '잘 쓰는 사람이 인정받는 분위기다'],\n    act: ['잘 쓰는 사람·팀을 공개적으로 인정', '월간 사용 현황 공유와 목표 설정', '업무 절차·양식에 Copilot 단계 넣기'] }\n];\nconst $ = id => document.getElementById(id);\nconst one = S.map(s => s.q.map(() => 0));\nlet groups = [{ n: '영업본부', v: [4.3, 3.8, 3.1, 2.6, 2.2] }, { n: '재무팀', v: [3.6, 2.4, 2.8, 2.1, 1.8] }, { n: '연구개발', v: [4.0, 4.1, 2.5, 2.3, 2.0] }];\nlet mode = 'one', sel = 0;\n\n$('one').innerHTML = '<h2>나의 변화 준비도 (각 문항 1~5점)</h2>' + S.map((s, i) => `<div class=\"stage\"><div class=\"nm\"><b>${s.k} · ${s.n}</b><span>${s.e}</span></div><div>` +\n  s.q.map((q, j) => `<div class=\"sq\"><p>${q}</p><div class=\"scale\" data-i=\"${i}\" data-j=\"${j}\">${[1, 2, 3, 4, 5].map(v => `<button data-v=\"${v}\">${v}</button>`).join('')}</div></div>`).join('') + '</div></div>').join('');\ndocument.querySelectorAll('.scale').forEach(x => x.onclick = e => { const b = e.target.closest('button'); if (!b) { return; } one[x.dataset.i][x.dataset.j] = Number(b.dataset.v); render(); });\n\nfunction drawGroups() {\n  $('groups').innerHTML = groups.map((g, gi) => `<div class=\"g\" data-g=\"${gi}\" style=\"${gi === sel ? 'border-color:var(--c1)' : ''}\"><label>그룹 이름</label><input value=\"${g.n.replace(/\"/g, '&quot;')}\" data-n>` +\n    S.map((s, i) => `<div class=\"sl\"><b>${s.k}</b><input type=\"range\" min=\"1\" max=\"5\" step=\"0.1\" value=\"${g.v[i]}\" data-i=\"${i}\"><span>${g.v[i].toFixed(1)}</span></div>`).join('') + '</div>').join('') +\n    '<div class=\"g\" style=\"display:grid;place-items:center\"><button class=\"pri\" id=\"addG\">그룹 추가</button></div>';\n  $('groups').querySelectorAll('.g[data-g]').forEach(el => {\n    const g = groups[el.dataset.g];\n    el.onclick = () => { if (sel !== Number(el.dataset.g)) { sel = Number(el.dataset.g); drawGroups(); render(); } };\n    el.querySelector('[data-n]').oninput = e => { g.n = e.target.value; render(); };\n    el.querySelectorAll('input[type=range]').forEach(r => r.oninput = () => { g.v[r.dataset.i] = Number(r.value); r.nextElementSibling.textContent = Number(r.value).toFixed(1); render(); });\n  });\n  $('addG').onclick = () => { groups.push({ n: '새 그룹', v: [3, 3, 3, 3, 3] }); sel = groups.length - 1; drawGroups(); render(); };\n}\n\nfunction vals() {\n  if (mode === 'team') { return groups[sel] ? groups[sel].v : [0, 0, 0, 0, 0]; }\n  return one.map(r => { const a = r.filter(Boolean); return a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0; });\n}\n\nfunction render() {\n  document.querySelectorAll('#one .scale').forEach(x => x.querySelectorAll('button').forEach(b => b.classList.toggle('on', one[x.dataset.i][x.dataset.j] === Number(b.dataset.v))));\n  const v = vals();\n  $('rtitle').textContent = mode === 'team' && groups[sel] ? `결과 · ${groups[sel].n}` : '결과 · 나의 변화 준비도';\n  const barrier = v.findIndex(x => x && x < 3);\n  const chart = $('chart');\n  chart.querySelectorAll('.col').forEach(c => c.remove());\n  v.forEach((x, i) => {\n    const c = document.createElement('div'); c.className = 'col';\n    c.innerHTML = `<div class=\"v\">${x ? x.toFixed(1) : '–'}</div><div class=\"b ${i === barrier ? 'barrier' : (x && x < 3.5 ? 'weak' : '')}\" style=\"height:0\"></div>`;\n    chart.appendChild(c);\n    requestAnimationFrame(() => requestAnimationFrame(() => { c.querySelector('.b').style.height = (x / 5 * 85) + '%'; }));\n  });\n  $('l3').style.bottom = (3 / 5 * 85) + '%';\n  $('labels').innerHTML = S.map(s => `<span><b>${s.k}</b> ${s.n}<small>${s.e}</small></span>`).join('');\n  const answered = v.filter(Boolean).length;\n  if (!answered) { $('verdict').innerHTML = '<div class=\"ic\">📝</div><div><h3>문항에 답해 주세요</h3>답하는 대로 그래프가 그려져요.</div>'; return; }\n  if (barrier < 0) {\n    $('verdict').innerHTML = `<div class=\"ic\">🚀</div><div><h3>막힌 단계가 없어요</h3>모든 단계가 3점 이상이에요. 정착(R) 단계를 더 강화해 습관으로 만드세요.<ul>${S[4].act.map(a => `<li>${a}</li>`).join('')}</ul></div>`;\n  } else {\n    const s = S[barrier];\n    $('verdict').innerHTML = `<div class=\"ic\">🚧</div><div><h3>막힌 지점: ${s.k} · ${s.n} (${v[barrier].toFixed(1)}점)</h3>이 단계를 풀기 전에는 뒤 단계(${S.slice(barrier + 1).map(x => x.n).join(' → ') || '없음'}) 활동의 효과가 작아요. 먼저 이렇게 해 보세요.<ul>${s.act.map(a => `<li>${a}</li>`).join('')}</ul></div>`;\n  }\n}\n\ndocument.querySelectorAll('.tabs button').forEach(b => b.onclick = () => {\n  mode = b.dataset.m; document.querySelectorAll('.tabs button').forEach(x => x.classList.toggle('on', x === b));\n  $('one').hidden = mode !== 'one'; $('team').hidden = mode !== 'team'; if (mode === 'team') { drawGroups(); } render();\n});\n$('copy').onclick = () => {\n  const v = vals();\n  const txt = `[ADKAR 변화 준비도] ${$('rtitle').textContent.replace('결과 · ', '')}\\n` + S.map((s, i) => `- ${s.k} ${s.n}: ${v[i] ? v[i].toFixed(1) : '–'}`).join('\\n') + '\\n\\n' + $('verdict').innerText;\n  navigator.clipboard.writeText(txt); $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '결과 복사'; }, 1500);\n};\nrender();\n</script>\n</body>\n</html>\n"},{"file":"project-status-dashboard.html","Title":"프로젝트 현황 대시보드 (PMO)","Summary":"단계 일정 · 마일스톤 · 위험 히트맵 · 신호등 상태를 한 화면에","Category":"대시보드","WorkArea":["프로젝트·사내 업무 하기"],"Tools":["Claude"],"Scope":["고객 프로젝트용"],"Does":"단계 · 마일스톤 · 위험을 한 줄씩 적으면 간트 차트와 위험 히트맵을 그려요\n계획 대비 진행률과 위험 수준으로 종합 상태(정상 · 주의 · 위험)를 판단해요\n고객 주간 보고에 넣을 문장을 만들어 복사할 수 있어요\n인쇄 · PDF로 바로 보고 자료가 돼요","MakerNote":"매주 고객 보고 때마다 PPT 일정표를 손으로 고치던 걸 없애려고 만들었어요. 내용은 이 브라우저에 저장돼요.","Output":"프로젝트 현황 한 장 · 주간 보고 문장","rel":[["1.0","처음 공유",15],["1.1","종합 상태 자동 판단 추가",2]],"text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>프로젝트 현황 대시보드</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--g:#1a8f63;--a:#d98a06;--r:#cf3f3f;--bar:#0a6cbd;--bar2:#b9d7f0}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--g:#45c492;--a:#f0a83a;--r:#ff7a7a;--bar:#80CAFF;--bar2:#2b4866}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:28px 20px 60px}\n.top{display:flex;justify-content:space-between;align-items:flex-end;gap:16px;flex-wrap:wrap;margin-bottom:18px}\nh1{font-size:26px;margin:0;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:4px 0 0}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center}\n.card h2 small{font-weight:500;color:var(--sub);font-size:12px}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px}\n.kpi .l{color:var(--sub);font-size:13px}\n.kpi .v{font-size:30px;font-weight:800;letter-spacing:-.02em;margin-top:2px}\n.kpi .d{font-size:13px;color:var(--sub)}\n.rag{display:inline-flex;align-items:center;gap:8px;font-weight:800;font-size:24px}\n.dot{width:16px;height:16px;border-radius:50%;display:inline-block}\n.G{background:var(--g)}.A{background:var(--a)}.R{background:var(--r)}\n.grid2{display:grid;grid-template-columns:3fr 2fr;gap:16px}\n.gantt{position:relative}\n.gr{display:grid;grid-template-columns:150px 1fr 48px;gap:10px;align-items:center;margin:10px 0;font-size:14px}\n.gt{position:relative;height:26px;background:var(--soft);border-radius:6px}\n.gb{position:absolute;top:0;bottom:0;border-radius:6px;background:var(--bar2);overflow:hidden}\n.gb i{position:absolute;left:0;top:0;bottom:0;background:var(--bar);border-radius:6px;width:0;transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.gb.late i{background:var(--a)}\n.today{position:absolute;top:-6px;bottom:-6px;width:2px;background:var(--r);z-index:2}\n.today span{position:absolute;top:-16px;left:50%;transform:translateX(-50%);font-size:11px;color:var(--r);white-space:nowrap;font-weight:700}\n.months{display:grid;grid-template-columns:150px 1fr 48px;gap:10px;font-size:11px;color:var(--sub)}\n.months div{position:relative;height:16px}\n.months span{position:absolute;transform:translateX(-50%)}\n.pct{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}\n.heat{display:grid;grid-template-columns:28px repeat(3,1fr);grid-template-rows:repeat(3,72px) 24px;gap:6px}\n.cell{border-radius:10px;padding:6px;display:flex;flex-wrap:wrap;gap:4px;align-content:flex-start;position:relative}\n.cell b{font-size:11px;background:var(--card);border-radius:999px;padding:2px 8px;cursor:default;box-shadow:0 1px 3px rgba(0,0,0,.15)}\n.ax{font-size:11px;color:var(--sub);display:grid;place-items:center}\n.ax.v{writing-mode:vertical-rl;transform:rotate(180deg)}\n.ms{list-style:none;margin:0;padding:0}\n.ms li{display:grid;grid-template-columns:20px 1fr auto;gap:10px;align-items:center;padding:9px 0;border-top:1px solid var(--line);font-size:14px}\n.ms li:first-child{border-top:0}\n.ms .st{font-size:12px;font-weight:700;padding:2px 9px;border-radius:999px}\n.done{color:var(--g)}.over{color:var(--r)}.soon{color:var(--a)}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth,td{padding:9px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}\nth{color:var(--sub);font-weight:600;font-size:13px}\n.lv{font-weight:800}\n.summary{white-space:pre-wrap;background:var(--soft);border-radius:12px;padding:16px;font-size:14px;margin:0}\ntextarea{width:100%;min-height:260px;border:1px solid var(--line);border-radius:10px;padding:12px;font:13px/1.6 Consolas,monospace;background:var(--bg);color:var(--ink)}\nbutton{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost{background:var(--soft);color:var(--ink)}\n.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.hint{font-size:12px;color:var(--sub)}\ndetails summary{cursor:pointer;font-weight:700}\n@media (max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.grid2{grid-template-columns:1fr}.gr,.months{grid-template-columns:96px 1fr 40px}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <div class=\"top\">\n    <div><h1 id=\"pname\">프로젝트 현황 대시보드</h1><p class=\"lead\" id=\"pmeta\"></p></div>\n    <div class=\"row\" style=\"margin:0\"><button id=\"copy\">주간 보고 문장 복사</button><button class=\"ghost\" onclick=\"window.print()\">인쇄 · PDF</button></div>\n  </div>\n  <div class=\"kpis\" id=\"kpis\"></div>\n  <div class=\"card\"><h2>단계별 일정 <small>막대 = 계획 기간 · 진한 부분 = 진행률 · 빨간 선 = 기준일</small></h2><div class=\"months\" id=\"months\"></div><div class=\"gantt\" id=\"gantt\"></div></div>\n  <div class=\"grid2\">\n    <div class=\"card\"><h2>위험 히트맵 <small>가능성 × 영향</small></h2><div class=\"heat\" id=\"heat\"></div></div>\n    <div class=\"card\"><h2>마일스톤</h2><ul class=\"ms\" id=\"ms\"></ul></div>\n  </div>\n  <div class=\"card\"><h2>위험 · 이슈 목록</h2><table id=\"risks\"></table></div>\n  <div class=\"card\"><h2>이번 주 보고 문장</h2><p class=\"summary\" id=\"sum\"></p></div>\n  <div class=\"card\">\n    <details><summary>데이터 편집 (우리 프로젝트로 바꾸기)</summary>\n      <p class=\"hint\">한 줄에 하나씩, 칸은 | 로 나눠요. 고치면 바로 대시보드에 반영돼요. 이 브라우저에 저장돼요.</p>\n      <textarea id=\"src\" spellcheck=\"false\"></textarea>\n      <div class=\"row\"><button class=\"ghost\" id=\"reset\">예시로 되돌리기</button></div>\n    </details>\n  </div>\n</div>\n<script>\nconst SAMPLE = `프로젝트: 고객사 A · Microsoft 365 Copilot 도입 컨설팅\n기간: 2026-10-05 | 2027-01-29\n기준일: 2026-11-20\n단계: 준비 · 데이터 거버넌스 점검 | 2026-10-05 | 2026-10-30 | 100\n단계: 시나리오 발굴 · 워크숍 | 2026-10-19 | 2026-11-13 | 100\n단계: 파일럿 (200명) | 2026-11-02 | 2026-12-11 | 55\n단계: 교육 · 챔피언 운영 | 2026-11-09 | 2027-01-15 | 30\n단계: 전사 확산 준비 | 2026-12-07 | 2027-01-22 | 0\n단계: 효과 측정 · 최종 보고 | 2027-01-11 | 2027-01-29 | 0\n마일스톤: 킥오프 | 2026-10-06 | Y\n마일스톤: 오버셰어링 점검 결과 보고 | 2026-10-30 | Y\n마일스톤: 파일럿 시작 | 2026-11-02 | Y\n마일스톤: 챔피언 1차 모임 | 2026-11-18 | N\n마일스톤: 파일럿 중간 보고 | 2026-11-27 | N\n마일스톤: 전사 확산 의사결정 | 2026-12-18 | N\n마일스톤: 최종 보고 | 2027-01-29 | N\n위험: 민감도 레이블 정책 승인 지연 | 3 | 3 | 고객 보안팀 | 12/4 보안위원회 안건 상정\n위험: 재무팀 파일럿 참여율 저조 | 2 | 3 | 컨설팅 PM | 재무 맞춤 교육 · 챔피언 지정\n위험: 라이선스 추가 구매 일정 미정 | 2 | 2 | 고객 IT | 12월 예산 회의에서 확정\n위험: 교육장 일정 충돌 | 1 | 2 | 고객 HR | 온라인 교육으로 대체 가능\n위험: 경영진 스폰서 메시지 지연 | 1 | 3 | 고객 스폰서 | 초안 전달 완료, 11/25 발송 예정`;\nconst KEY = 'pmo-dash-v1';\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nconst D = s => new Date(s + 'T00:00:00');\nconst ymd = d => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, \"0\")}-${String(d.getDate()).padStart(2, \"0\")}`;\nconst md = d => `${d.getMonth() + 1}/${d.getDate()}`;\nconst days = (a, b) => Math.round((b - a) / 86400000);\n\nfunction parse(t) {\n  const p = { name: '', start: null, end: null, today: new Date(), phases: [], ms: [], risks: [] };\n  t.split(/\\r?\\n/).forEach(l => {\n    const m = /^\\s*([^:]+):\\s*(.*)$/.exec(l); if (!m) { return; }\n    const k = m[1].trim(), v = m[2].split('|').map(s => s.trim());\n    if (k === '프로젝트') { p.name = v.join(' | '); }\n    else if (k === '기간') { p.start = D(v[0]); p.end = D(v[1]); }\n    else if (k === '기준일') { p.today = D(v[0]); }\n    else if (k === '단계') { p.phases.push({ n: v[0], s: D(v[1]), e: D(v[2]), p: Number(v[3]) || 0 }); }\n    else if (k === '마일스톤') { p.ms.push({ n: v[0], d: D(v[1]), done: /^y/i.test(v[2] || '') }); }\n    else if (k === '위험') { p.risks.push({ n: v[0], pr: Math.min(3, Math.max(1, Number(v[1]) || 1)), im: Math.min(3, Math.max(1, Number(v[2]) || 1)), o: v[3] || '', a: v[4] || '' }); }\n  });\n  if (!p.start && p.phases.length) { p.start = new Date(Math.min(...p.phases.map(x => x.s))); p.end = new Date(Math.max(...p.phases.map(x => x.e))); }\n  return p;\n}\n\nfunction render() {\n  const p = parse($('src').value);\n  if (!p.start || !p.phases.length) { return; }\n  try { localStorage.setItem(KEY, $('src').value); } catch (e) { /* 저장 못 해도 계속 */ }\n  const span = days(p.start, p.end) || 1;\n  const pos = d => Math.min(100, Math.max(0, days(p.start, d) / span * 100));\n  // 단계별 기대 진행률 = 기준일까지 지난 기간 비율\n  const exp = ph => Math.min(100, Math.max(0, days(ph.s, p.today) / Math.max(1, days(ph.s, ph.e)) * 100));\n  const totalW = p.phases.reduce((s, x) => s + days(x.s, x.e), 0) || 1;\n  const prog = p.phases.reduce((s, x) => s + x.p * days(x.s, x.e), 0) / totalW;\n  const plan = p.phases.reduce((s, x) => s + exp(x) * days(x.s, x.e), 0) / totalW;\n  const gap = prog - plan;\n  const lev = r => r.pr * r.im;\n  const high = p.risks.filter(r => lev(r) >= 6).length;\n  const overMs = p.ms.filter(m => !m.done && m.d < p.today);\n  const rag = high >= 2 || gap < -15 || overMs.length >= 2 ? 'R' : high >= 1 || gap < -5 || overMs.length ? 'A' : 'G';\n  const ragTxt = { G: '정상', A: '주의', R: '위험' }[rag];\n  $('pname').textContent = p.name || '프로젝트 현황 대시보드';\n  $('pmeta').textContent = `기간 ${ymd(p.start)} ~ ${ymd(p.end)} · 기준일 ${md(p.today)} · 남은 기간 ${Math.max(0, days(p.today, p.end))}일`;\n  $('kpis').innerHTML = [\n    ['종합 상태', `<span class=\"rag\"><span class=\"dot ${rag}\"></span>${ragTxt}</span>`, `높은 위험 ${high}건 · 지난 마일스톤 미완료 ${overMs.length}건`],\n    ['전체 진행률', Math.round(prog) + '%', `계획 ${Math.round(plan)}% 대비 <b class=\"${gap >= -5 ? 'done' : gap >= -15 ? 'soon' : 'over'}\">${gap >= 0 ? '+' : ''}${Math.round(gap)}%p</b>`],\n    ['마일스톤', `${p.ms.filter(m => m.done).length} / ${p.ms.length}`, (() => { const n = p.ms.filter(m => !m.done).sort((a, b) => a.d - b.d)[0]; return n ? `다음: ${esc(n.n)} (${md(n.d)})` : '모두 완료'; })()],\n    ['열린 위험 · 이슈', p.risks.length + '건', `높음 ${high} · 중간 ${p.risks.filter(r => lev(r) >= 3 && lev(r) < 6).length} · 낮음 ${p.risks.filter(r => lev(r) < 3).length}`]\n  ].map(k => `<div class=\"kpi\"><div class=\"l\">${k[0]}</div><div class=\"v\">${k[1]}</div><div class=\"d\">${k[2]}</div></div>`).join('');\n\n  const ticks = []; const c = new Date(p.start.getFullYear(), p.start.getMonth() + 1, 1);\n  while (c <= p.end) { ticks.push(new Date(c)); c.setMonth(c.getMonth() + 1); }\n  $('months').innerHTML = `<div></div><div>${ticks.map(t => `<span style=\"left:${pos(t)}%\">${t.getMonth() + 1}월</span>`).join('')}</div><div></div>`;\n  $('gantt').innerHTML = p.phases.map(ph => {\n    const late = ph.p + 10 < exp(ph);\n    return `<div class=\"gr\"><span>${esc(ph.n)}</span><div class=\"gt\"><div class=\"gb ${late ? 'late' : ''}\" style=\"left:${pos(ph.s)}%;width:${pos(ph.e) - pos(ph.s)}%\"><i data-w=\"${ph.p}\"></i></div>\n      <div class=\"today\" style=\"left:${pos(p.today)}%\">${ph === p.phases[0] ? `<span>기준일 ${md(p.today)}</span>` : ''}</div></div><span class=\"pct\">${ph.p}%</span></div>`;\n  }).join('');\n  requestAnimationFrame(() => requestAnimationFrame(() => document.querySelectorAll('.gb i').forEach(i => { i.style.width = i.dataset.w + '%'; })));\n\n  const col = (pr, im) => { const v = pr * im; return v >= 6 ? 'rgba(207,63,63,.28)' : v >= 3 ? 'rgba(217,138,6,.25)' : 'rgba(26,143,99,.2)'; };\n  let h = '';\n  [3, 2, 1].forEach(pr => {\n    h += `<div class=\"ax v\">${['', '낮음', '중간', '높음'][pr]}</div>`;\n    [1, 2, 3].forEach(im => { h += `<div class=\"cell\" style=\"background:${col(pr, im)}\">${p.risks.map((r, i) => r.pr === pr && r.im === im ? `<b title=\"${esc(r.n)}\">R${i + 1}</b>` : '').join('')}</div>`; });\n  });\n  h += '<div></div>' + ['낮음', '중간', '높음'].map(x => `<div class=\"ax\">영향 ${x}</div>`).join('');\n  $('heat').innerHTML = h;\n\n  $('ms').innerHTML = [...p.ms].sort((a, b) => a.d - b.d).map(m => {\n    const st = m.done ? ['완료', 'done', '✔'] : m.d < p.today ? ['지연', 'over', '!'] : days(p.today, m.d) <= 7 ? ['이번 주', 'soon', '•'] : ['예정', '', '○'];\n    return `<li><span class=\"${st[1]}\">${st[2]}</span><span>${esc(m.n)} <span class=\"hint\">${md(m.d)}</span></span><span class=\"st ${st[1]}\" style=\"background:var(--soft)\">${st[0]}</span></li>`;\n  }).join('');\n\n  $('risks').innerHTML = '<tr><th>ID</th><th>위험 · 이슈</th><th>수준</th><th>담당</th><th>대응</th></tr>' +\n    p.risks.map((r, i) => ({ r, i })).sort((a, b) => lev(b.r) - lev(a.r)).map(({ r, i }) => { const l = lev(r); const t = l >= 6 ? ['높음', 'over'] : l >= 3 ? ['중간', 'soon'] : ['낮음', 'done']; return `<tr><td>R${i + 1}</td><td>${esc(r.n)}</td><td class=\"lv ${t[1]}\">${t[0]}</td><td>${esc(r.o)}</td><td>${esc(r.a)}</td></tr>`; }).join('');\n\n  const next = p.ms.filter(m => !m.done && m.d >= p.today).sort((a, b) => a.d - b.d).slice(0, 2);\n  const top = [...p.risks].sort((a, b) => lev(b) - lev(a)).slice(0, 2);\n  $('sum').textContent = [\n    `■ 종합 상태: ${ragTxt} · 전체 진행률 ${Math.round(prog)}% (계획 대비 ${gap >= 0 ? '+' : ''}${Math.round(gap)}%p)`,\n    `■ 진행 중: ${p.phases.filter(x => x.p > 0 && x.p < 100).map(x => `${x.n} ${x.p}%`).join(', ') || '없음'}`,\n    overMs.length ? `■ 지연 마일스톤: ${overMs.map(m => `${m.n}(${md(m.d)})`).join(', ')}` : '■ 지연된 마일스톤은 없습니다.',\n    next.length ? `■ 다음 마일스톤: ${next.map(m => `${m.n}(${md(m.d)})`).join(', ')}` : '',\n    top.length ? `■ 주요 위험: ${top.map(r => `${r.n} → ${r.a}`).join(' / ')}` : '',\n    high ? `■ 요청 사항: 높은 위험 ${high}건에 대한 고객 측 의사결정을 부탁드립니다.` : ''\n  ].filter(Boolean).join('\\n');\n}\n\nlet saved = null; try { saved = localStorage.getItem(KEY); } catch (e) { saved = null; }\n$('src').value = saved || SAMPLE;\n$('src').oninput = render;\n$('reset').onclick = () => { $('src').value = SAMPLE; render(); };\n$('copy').onclick = () => { navigator.clipboard.writeText($('sum').textContent); $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '주간 보고 문장 복사'; }, 1500); };\nrender();\n</script>\n</body>\n</html>\n"},{"file":"pilot-impact-dashboard.html","Title":"파일럿 효과 측정 대시보드","Summary":"사전 · 사후 설문으로 절감 시간 · 만족도 · NPS와 확산 효과를 계산해요","Category":"대시보드","WorkArea":["데이터로 인사이트 찾기"],"Tools":["Claude","Copilot"],"Scope":["고객 프로젝트용"],"Does":"Forms 설문 결과를 붙여 넣으면 시나리오별 · 부서별 절감 시간을 보여 줘요\n만족도 분포와 추천 의향(NPS)을 계산해요\n확산 인원과 인건비를 넣으면 연간 기대 효과를 보수 · 기준으로 계산해요\n확산 의사결정 보고 요약을 만들어 복사할 수 있어요","MakerNote":"파일럿 끝나고 \"그래서 확산해요?\"에 답할 근거를 하루 만에 만들려고 만들었어요.","Output":"파일럿 효과 요약 · 확산 시 기대 효과","rel":[["1.0","처음 공유",10]],"text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>파일럿 효과 측정 대시보드</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--warn:#d98a06;--bad:#cf3f3f;--c1:#0a6cbd;--c2:#9cc9ee}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--warn:#f0a83a;--bad:#ff7a7a;--c1:#80CAFF;--c2:#35587a}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 20px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center;gap:8px}\n.card h2 small{font-weight:500;color:var(--sub);font-size:12px}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px}\n.kpi .l{color:var(--sub);font-size:13px}\n.kpi .v{font-size:30px;font-weight:800;letter-spacing:-.02em;margin-top:2px;font-variant-numeric:tabular-nums}\n.kpi .d{font-size:13px;color:var(--sub)}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.bars .b{display:grid;grid-template-columns:150px 1fr 90px;gap:10px;align-items:center;margin:10px 0;font-size:14px}\n.pair{display:flex;flex-direction:column;gap:3px}\n.track{height:11px;background:var(--soft);border-radius:999px;overflow:hidden}\n.track i{display:block;height:100%;border-radius:999px;width:0;transition:width .8s cubic-bezier(.2,.8,.2,1)}\n.num{text-align:right;font-variant-numeric:tabular-nums;font-weight:700}\n.legend{display:flex;gap:16px;font-size:12px;color:var(--sub);margin-top:4px}\n.legend i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}\n.nps{display:flex;height:34px;border-radius:10px;overflow:hidden;font-size:12px;font-weight:700;color:#fff}\n.nps div{display:grid;place-items:center;transition:flex .6s}\n.dist{display:grid;grid-template-columns:repeat(5,1fr);gap:8px;align-items:end;height:150px;margin-top:14px}\n.dist .c{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;font-size:12px;color:var(--sub)}\n.dist .c i{width:100%;max-width:56px;background:var(--c1);border-radius:8px 8px 0 0;transition:height .6s}\n.dist .c b{color:var(--ink);font-size:13px}\n.proj{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n.proj .p{background:var(--soft);border-radius:12px;padding:14px}\n.proj .p .l{font-size:13px;color:var(--sub)}\n.proj .p .v{font-size:22px;font-weight:800;font-variant-numeric:tabular-nums}\n.proj label{font-size:14px;display:flex;gap:8px;align-items:center;margin-bottom:12px}\n.proj input,label.inl input{width:110px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;background:var(--bg);color:var(--ink);font:inherit}\n.quotes{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.q{border-left:3px solid var(--c1);background:var(--soft);border-radius:0 10px 10px 0;padding:10px 14px;font-size:14px}\n.q small{display:block;color:var(--sub);font-size:12px;margin-top:4px}\n.summary{white-space:pre-wrap;background:var(--soft);border-radius:12px;padding:16px;font-size:14px;margin:0}\ntextarea{width:100%;min-height:180px;border:1px solid var(--line);border-radius:10px;padding:12px;font:12px/1.5 Consolas,monospace;background:var(--bg);color:var(--ink)}\nbutton,.file{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost,.file{background:var(--soft);color:var(--ink)}\n.file input{display:none}\n.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px;align-items:center}\n.hint{font-size:12px;color:var(--sub)}\n.err{color:var(--bad);font-size:14px}\ndetails summary{cursor:pointer;font-weight:700}\n@media (max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.grid2,.quotes,.proj{grid-template-columns:1fr}.bars .b{grid-template-columns:96px 1fr 70px}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>Copilot 파일럿 효과 측정 대시보드</h1>\n  <p class=\"lead\">파일럿 참가자의 사전 · 사후 설문 결과를 붙여 넣으면 절감 시간, 만족도, 추천 의향(NPS)과 전사 확산 시 기대 효과를 계산해요. 확산 의사결정 보고에 바로 쓰세요.</p>\n  <div class=\"kpis\" id=\"kpis\"></div>\n  <div class=\"grid2\">\n    <div class=\"card\"><h2>시나리오별 주당 업무 시간 <small>사전 vs 사후 (1인 평균)</small></h2><div class=\"bars\" id=\"scen\"></div>\n      <div class=\"legend\"><span><i style=\"background:var(--c2)\"></i>사전</span><span><i style=\"background:var(--c1)\"></i>사후</span></div></div>\n    <div class=\"card\"><h2>부서별 1인 주당 절감 시간</h2><div class=\"bars\" id=\"dept\"></div></div>\n  </div>\n  <div class=\"grid2\">\n    <div class=\"card\"><h2>추천 의향 (NPS) <small>0~10점 중 9~10 추천 · 0~6 비추천</small></h2><div class=\"nps\" id=\"nps\"></div><div class=\"legend\" id=\"npsl\"></div>\n      <h2 style=\"margin-top:22px\">만족도 분포</h2><div class=\"dist\" id=\"dist\"></div></div>\n    <div class=\"card\"><h2>전사 확산 시 기대 효과</h2>\n      <div class=\"proj\"><label style=\"grid-column:1/-1\">확산 대상 인원 <input type=\"number\" id=\"n\" value=\"1500\" step=\"100\"> 명 · 시간당 인건비 <input type=\"number\" id=\"w\" value=\"45000\" step=\"5000\"> 원</label>\n        <div class=\"p\"><div class=\"l\">연간 절감 시간</div><div class=\"v\" id=\"ph\"></div></div>\n        <div class=\"p\"><div class=\"l\">연간 절감 금액</div><div class=\"v\" id=\"pw\"></div></div>\n        <div class=\"p\"><div class=\"l\">정규직 환산</div><div class=\"v\" id=\"pf\"></div></div></div>\n      <p class=\"hint\">파일럿 1인 평균 절감 시간 × 확산 인원 × 46주. 파일럿 참가자는 적극적인 사람이 많아 실제로는 60~70% 수준을 기대하는 것이 안전해요 (아래 보수 추정).</p>\n      <p class=\"hint\" id=\"cons\"></p>\n      <h2 style=\"margin-top:18px\">참가자 목소리</h2><div class=\"quotes\" id=\"quotes\"></div></div>\n  </div>\n  <div class=\"card\"><h2>확산 의사결정 보고 요약</h2><p class=\"summary\" id=\"sum\"></p><div class=\"row\"><button id=\"copy\">요약 복사</button></div></div>\n  <div class=\"card\"><details><summary>설문 데이터 바꾸기</summary>\n    <p class=\"hint\">머리글: 부서, 시나리오, 사전 시간, 사후 시간, 만족도, 추천, 의견 (사전 · 사후 시간은 그 업무에 쓰는 주당 시간). Forms 결과를 Excel에서 복사해 붙여도 돼요.</p>\n    <textarea id=\"src\" spellcheck=\"false\"></textarea>\n    <div class=\"row\"><button id=\"run\">다시 계산</button><label class=\"file\">CSV 파일 열기<input type=\"file\" id=\"file\" accept=\".csv,.txt\"></label><button class=\"ghost\" id=\"sample\">예시 데이터</button><span class=\"err\" id=\"err\"></span></div>\n  </details></div>\n</div>\n<script>\nconst SAMPLE = (() => {\n  const rows = [['부서', '시나리오', '사전 시간', '사후 시간', '만족도', '추천', '의견']];\n  const S = [['회의록 요약', 3.0, 1.0], ['메일 정리 · 답장', 4.0, 2.4], ['보고서 초안', 5.0, 2.6], ['자료 검색', 3.0, 1.5], ['엑셀 분석', 2.5, 1.7]];\n  const Dp = [['영업본부', 1.1], ['마케팅팀', 1.15], ['재무팀', 0.7], ['인사팀', 0.95], ['고객지원', 1.05]];\n  const Q = ['회의 끝나고 회의록 쓰는 시간이 거의 없어졌어요', '메일 답장 초안이 생각보다 자연스러워요', '숫자는 꼭 다시 확인해야 해서 아직 조심스러워요', '보고서 첫 장을 쓰는 부담이 사라졌어요', '자료 찾는 시간이 반으로 줄었어요', '엑셀은 아직 기대보다 덜 정확해요', '교육을 한 번 더 받고 싶어요', '팀 전체에 바로 쓰게 해 주세요'];\n  let seed = 7; const rnd = () => { seed = (seed * 9301 + 49297) % 233280; return seed / 233280; };\n  for (let i = 0; i < 120; i++) {\n    const s = S[i % S.length], d = Dp[Math.floor(rnd() * Dp.length)];\n    const pre = +(s[1] * (0.8 + rnd() * 0.5)).toFixed(1);\n    const post = +Math.max(0.2, pre - (s[1] - s[2]) * d[1] * (0.6 + rnd() * 0.8)).toFixed(1);\n    const sat = Math.min(5, Math.max(1, Math.round(3.4 + d[1] * 0.9 + (rnd() - 0.5) * 2.4)));\n    const rec = Math.min(10, Math.max(0, Math.round(sat * 1.9 + (rnd() - 0.4) * 3)));\n    rows.push([d[0], s[0], pre, post, sat, rec, i % 9 === 0 ? Q[(i / 9) % Q.length] : '']);\n  }\n  return rows.map(r => r.join(',')).join('\\n');\n})();\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nconst won = n => n >= 1e8 ? (n / 1e8).toFixed(1) + '억 원' : Math.round(n / 1e4).toLocaleString('ko-KR') + '만 원';\nconst avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : 0;\nlet rows = [];\n\nfunction parse(t) {\n  const lines = t.trim().split(/\\r?\\n/).filter(Boolean);\n  const sep = lines[0].includes('\\t') ? '\\t' : ',';\n  const h = lines[0].split(sep).map(s => s.replace(/\\s/g, ''));\n  const f = (...n) => h.findIndex(x => n.some(k => x.includes(k)));\n  const ix = { d: f('부서'), s: f('시나리오', '업무'), a: f('사전'), b: f('사후'), sat: f('만족'), rec: f('추천', 'NPS'), c: f('의견', '코멘트') };\n  if (ix.a < 0 || ix.b < 0) { throw new Error('사전 시간 · 사후 시간 열을 찾지 못했어요.'); }\n  return lines.slice(1).map(l => { const c = l.split(sep); return { d: c[ix.d] || '전체', s: c[ix.s] || '기타', a: +c[ix.a] || 0, b: +c[ix.b] || 0, sat: +c[ix.sat] || 0, rec: ix.rec >= 0 && c[ix.rec] !== '' ? +c[ix.rec] : null, c: ix.c >= 0 ? (c.slice(ix.c).join(sep) || '').trim() : '' }; });\n}\nconst group = (k) => { const m = {}; rows.forEach(r => { (m[r[k]] = m[r[k]] || []).push(r); }); return m; };\n\nfunction render() {\n  $('err').textContent = '';\n  try { rows = parse($('src').value); } catch (e) { $('err').textContent = e.message; return; }\n  const saved = rows.map(r => r.a - r.b);\n  // 응답자 1명 = 1행(시나리오 1개) 기준. 1인 주당 절감 = 응답 평균 × 1인당 시나리오 수(행 수 ÷ 고유 응답자 수를 알 수 없어 시나리오 수로 근사)\n  const perPerson = avg(saved) * Math.min(3, Object.keys(group('s')).length);\n  const pctSaved = rows.filter(r => r.a - r.b > 0.2).length / rows.length;\n  const sat = avg(rows.filter(r => r.sat).map(r => r.sat));\n  const recs = rows.filter(r => r.rec !== null);\n  const pro = recs.filter(r => r.rec >= 9).length / (recs.length || 1), det = recs.filter(r => r.rec <= 6).length / (recs.length || 1);\n  const nps = Math.round((pro - det) * 100);\n  const cut = avg(rows.map(r => r.a ? (r.a - r.b) / r.a : 0));\n  $('kpis').innerHTML = [\n    ['1인 주당 절감 시간', perPerson.toFixed(1) + '시간', `시나리오 평균 ${avg(saved).toFixed(1)}시간 × 주요 3개`],\n    ['업무 시간 감소율', Math.round(cut * 100) + '%', `시간이 줄었다는 응답 ${Math.round(pctSaved * 100)}%`],\n    ['평균 만족도', sat.toFixed(1) + ' / 5', `4점 이상 ${Math.round(rows.filter(r => r.sat >= 4).length / rows.length * 100)}%`],\n    ['추천 의향 NPS', (nps > 0 ? '+' : '') + nps, nps >= 30 ? '확산 권장 수준' : nps >= 0 ? '보완 후 확산' : '원인 분석 필요']\n  ].map(k => `<div class=\"kpi\"><div class=\"l\">${k[0]}</div><div class=\"v\">${k[1]}</div><div class=\"d\">${k[2]}</div></div>`).join('');\n\n  const sg = Object.entries(group('s')).map(([k, v]) => ({ k, a: avg(v.map(r => r.a)), b: avg(v.map(r => r.b)) })).sort((x, y) => (y.a - y.b) - (x.a - x.b));\n  const mx = Math.max(...sg.map(x => x.a)) || 1;\n  $('scen').innerHTML = sg.map(x => `<div class=\"b\"><span>${esc(x.k)}</span><div class=\"pair\"><div class=\"track\"><i style=\"background:var(--c2)\" data-w=\"${x.a / mx * 100}\"></i></div><div class=\"track\"><i style=\"background:var(--c1)\" data-w=\"${x.b / mx * 100}\"></i></div></div><span class=\"num\">−${Math.round((1 - x.b / x.a) * 100)}%</span></div>`).join('');\n  const dg = Object.entries(group('d')).map(([k, v]) => ({ k, s: avg(v.map(r => r.a - r.b)) * Math.min(3, sg.length), n: v.length })).sort((x, y) => y.s - x.s);\n  const md = Math.max(...dg.map(x => x.s)) || 1;\n  $('dept').innerHTML = dg.map(x => `<div class=\"b\"><span>${esc(x.k)} <span class=\"hint\">${x.n}명</span></span><div class=\"track\" style=\"height:18px\"><i style=\"background:${x.s < perPerson * 0.75 ? 'var(--warn)' : 'var(--c1)'}\" data-w=\"${x.s / md * 100}\"></i></div><span class=\"num\">${x.s.toFixed(1)}시간</span></div>`).join('');\n\n  const pas = 1 - pro - det;\n  $('nps').innerHTML = `<div style=\"flex:${det};background:var(--bad)\">${Math.round(det * 100)}%</div><div style=\"flex:${pas};background:#8a97a6\">${Math.round(pas * 100)}%</div><div style=\"flex:${pro};background:var(--ok)\">${Math.round(pro * 100)}%</div>`;\n  $('npsl').innerHTML = '<span><i style=\"background:var(--bad)\"></i>비추천 (0~6)</span><span><i style=\"background:#8a97a6\"></i>중립 (7~8)</span><span><i style=\"background:var(--ok)\"></i>추천 (9~10)</span>';\n  const cnt = [1, 2, 3, 4, 5].map(v => rows.filter(r => r.sat === v).length), cm = Math.max(...cnt) || 1;\n  $('dist').innerHTML = cnt.map((c, i) => `<div class=\"c\"><b>${c}</b><i style=\"height:0\" data-h=\"${c / cm * 85}\"></i>${i + 1}점</div>`).join('');\n\n  const proj = () => {\n    const n = +$('n').value || 0, w = +$('w').value || 0, hrs = perPerson * n * 46;\n    $('ph').textContent = Math.round(hrs).toLocaleString('ko-KR') + '시간'; $('pw').textContent = won(hrs * w); $('pf').textContent = (hrs / 1840).toFixed(0) + '명';\n    $('cons').textContent = `보수 추정(65%): 연간 ${Math.round(hrs * 0.65).toLocaleString('ko-KR')}시간 · ${won(hrs * 0.65 * w)}`;\n    return { n, hrs, w };\n  };\n  const P = proj(); $('n').oninput = $('w').oninput = () => { proj(); summary(); };\n  const qs = rows.filter(r => r.c).slice(0, 6);\n  $('quotes').innerHTML = qs.map(r => `<div class=\"q\">\"${esc(r.c)}\"<small>${esc(r.d)} · ${esc(r.s)} · 만족도 ${r.sat}</small></div>`).join('') || '<p class=\"hint\">의견 열이 없어요.</p>';\n\n  function summary() {\n    const p = proj();\n    $('sum').textContent = [\n      `■ 파일럿 참가자 응답 ${rows.length}건 기준, 1인당 주 ${perPerson.toFixed(1)}시간을 절감했습니다 (업무 시간 ${Math.round(cut * 100)}% 감소).`,\n      `■ 효과가 가장 큰 업무는 ${sg[0].k}(−${Math.round((1 - sg[0].b / sg[0].a) * 100)}%)와 ${sg[1] ? sg[1].k : ''}이며, ${sg[sg.length - 1].k}은 효과가 작아 교육 보완이 필요합니다.`,\n      `■ 만족도 ${sat.toFixed(1)}/5, 추천 의향 NPS ${nps > 0 ? '+' : ''}${nps}입니다.`,\n      `■ ${p.n.toLocaleString('ko-KR')}명으로 확산하면 연간 약 ${Math.round(p.hrs * 0.65).toLocaleString('ko-KR')}~${Math.round(p.hrs).toLocaleString('ko-KR')}시간(${won(p.hrs * 0.65 * p.w)}~${won(p.hrs * p.w)})의 절감이 기대됩니다.`,\n      `■ 제안: ${nps >= 30 ? '전사 확산을 승인하고' : '보완 교육 후 단계적으로 확산하고'}, ${dg[dg.length - 1].k}에는 업무 맞춤 교육과 챔피언을 먼저 배치합니다.`\n    ].join('\\n');\n  }\n  summary();\n  requestAnimationFrame(() => requestAnimationFrame(() => {\n    document.querySelectorAll('.track i').forEach(i => { i.style.width = i.dataset.w + '%'; });\n    document.querySelectorAll('.dist i').forEach(i => { i.style.height = i.dataset.h + '%'; });\n  }));\n}\n$('src').value = SAMPLE;\n$('run').onclick = render;\n$('sample').onclick = () => { $('src').value = SAMPLE; render(); };\n$('file').onchange = e => { const f = e.target.files[0]; if (!f) { return; } const r = new FileReader(); r.onload = () => { $('src').value = r.result; render(); }; r.readAsText(f, 'utf-8'); };\n$('copy').onclick = () => { navigator.clipboard.writeText($('sum').textContent); $('copy').textContent = '복사했어요'; setTimeout(() => { $('copy').textContent = '요약 복사'; }, 1500); };\nrender();\n</script>\n</body>\n</html>\n"},{"file":"adoption-funnel-dashboard.html","Title":"교육 · 확산 퍼널 대시보드","Summary":"라이선스 → 교육 → 첫 사용 → 주간 활성, 어디서 빠지는지 부서별로","Category":"대시보드","WorkArea":["교육·확산 프로그램 운영하기"],"Tools":["Claude"],"Scope":["고객 프로젝트용","사내 업무용"],"Does":"부서별 라이선스 · 교육 이수 · 첫 사용 · 주간 활성 숫자로 확산 퍼널을 그려요\n부서마다 가장 많이 빠지는 단계(병목)를 찾아 표시해요\n병목 단계에 맞는 처방(교육 방식, 첫 과제, 미션)을 추천해요\n주간 활성 사용률 추이를 부서별로 비교해요","MakerNote":"활성 사용률이 낮을 때 \"교육이 문제인지, 쓸 일이 없는 건지\" 구분하려고 만들었어요.","Output":"부서별 병목 단계 · 처방","rel":[["1.0","처음 공유",6]],"text":"<!doctype html>\n<html lang=\"ko\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>교육·확산 퍼널 대시보드</title>\n<style>\n:root{--bg:#f4f6f9;--card:#fff;--ink:#1d2733;--sub:#5d6b7b;--line:#e2e7ee;--pri:#003F6D;--onpri:#fff;--soft:#e8f2fb;--ok:#1a8f63;--warn:#d98a06;--bad:#cf3f3f;--f1:#003F6D;--f2:#0a5a96;--f3:#0a6cbd;--f4:#4f9ad8}\n@media (prefers-color-scheme:dark){:root{--bg:#0c141e;--card:#142131;--ink:#e5edf6;--sub:#9cafc3;--line:#25374c;--pri:#80CAFF;--onpri:#06233b;--soft:#1a2d44;--ok:#45c492;--warn:#f0a83a;--bad:#ff7a7a;--f1:#BFE3FF;--f2:#9fd3ff;--f3:#80CAFF;--f4:#4f9ad8}}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--ink);font:15px/1.55 Pretendard,\"Malgun Gothic\",\"Apple SD Gothic Neo\",system-ui,sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:28px 20px 60px}\nh1{font-size:26px;margin:0 0 4px;letter-spacing:-.02em}\n.lead{color:var(--sub);margin:0 0 20px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px;margin-bottom:16px}\n.card h2{font-size:16px;margin:0 0 14px;display:flex;justify-content:space-between;align-items:center;gap:8px}\n.card h2 small{font-weight:500;color:var(--sub);font-size:12px}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.funnel{display:flex;flex-direction:column;align-items:center;gap:6px}\n.fs{position:relative;height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;color:#fff;border-radius:10px;transition:width .8s cubic-bezier(.2,.8,.2,1);min-width:230px;font-weight:700}\n@media (prefers-color-scheme:dark){.fs{color:#06233b}}\n.fs small{font-weight:500;opacity:.85;font-size:12px;display:block}\n.fs .n{font-size:22px;font-variant-numeric:tabular-nums}\n.conv{font-size:12px;color:var(--sub);display:flex;align-items:center;gap:6px}\n.conv b{color:var(--ink)}\n.conv.neck b{color:var(--bad)}\n.neckTag{background:rgba(207,63,63,.14);color:var(--bad);border-radius:999px;padding:1px 8px;font-weight:700}\n.sel{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px}\n.sel button{border:1px solid var(--line);background:var(--bg);color:var(--ink);border-radius:999px;padding:6px 14px;font-weight:600;font-size:13px;font-family:inherit;cursor:pointer}\n.sel button.on{background:var(--pri);color:var(--onpri);border-color:var(--pri)}\ntable{width:100%;border-collapse:collapse;font-size:14px}\nth,td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:center}\nth:first-child,td:first-child{text-align:left}\nth{color:var(--sub);font-weight:600;font-size:12px}\ntd.h{font-weight:700;border-radius:6px;font-variant-numeric:tabular-nums}\n.trend svg text{fill:var(--sub);font-size:11px;font-family:inherit}\n.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:12px;color:var(--sub);margin-top:6px}\n.legend i{display:inline-block;width:10px;height:3px;margin-right:5px;vertical-align:3px}\n.acts{list-style:none;margin:0;padding:0}\n.acts li{display:grid;grid-template-columns:110px 1fr;gap:12px;padding:10px 0;border-top:1px solid var(--line);font-size:14px}\n.acts li:first-child{border-top:0}\n.acts b{color:var(--bad)}\ntextarea{width:100%;min-height:170px;border:1px solid var(--line);border-radius:10px;padding:12px;font:12px/1.5 Consolas,monospace;background:var(--bg);color:var(--ink)}\nbutton.pri{border:0;border-radius:999px;padding:9px 18px;font-weight:600;font-size:14px;font-family:inherit;cursor:pointer;background:var(--pri);color:var(--onpri)}\nbutton.ghost{background:var(--soft);color:var(--ink)}\n.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.hint{font-size:12px;color:var(--sub)}\ndetails summary{cursor:pointer;font-weight:700}\n@media (max-width:900px){.grid2{grid-template-columns:1fr}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <h1>교육 · 확산 퍼널 대시보드</h1>\n  <p class=\"lead\">라이선스를 받은 사람이 교육 → 첫 사용 → 매주 사용까지 얼마나 이어지는지 부서별로 보여 주고, 가장 많이 빠지는 단계(병목)와 맞는 처방을 알려 줘요.</p>\n  <div class=\"grid2\">\n    <div class=\"card\"><h2>확산 퍼널 <small id=\"fsub\"></small></h2><div class=\"sel\" id=\"sel\"></div><div class=\"funnel\" id=\"funnel\"></div></div>\n    <div class=\"card\"><h2>병목별 처방</h2><ul class=\"acts\" id=\"acts\"></ul></div>\n  </div>\n  <div class=\"card\"><h2>부서별 단계 전환율 <small>앞 단계 대비 다음 단계로 넘어간 비율 · 빨간 칸 = 그 부서의 병목</small></h2><table id=\"tbl\"></table></div>\n  <div class=\"card trend\"><h2>주간 활성 사용률 추이</h2><svg id=\"trend\" viewBox=\"0 0 900 260\" width=\"100%\"></svg><div class=\"legend\" id=\"tleg\"></div></div>\n  <div class=\"card\"><details><summary>데이터 바꾸기</summary>\n    <p class=\"hint\">부서별 퍼널: 부서, 라이선스, 교육 이수, 첫 사용, 주간 활성 · 그 아래 빈 줄 하나 띄우고 주간 추이: 주차, 부서1 활성률(%), 부서2 …</p>\n    <textarea id=\"src\" spellcheck=\"false\"></textarea>\n    <div class=\"row\"><button class=\"pri\" id=\"run\">다시 그리기</button><button class=\"pri ghost\" id=\"sample\">예시 데이터</button></div>\n  </details></div>\n</div>\n<script>\nconst SAMPLE = `부서,라이선스,교육 이수,첫 사용,주간 활성\n영업본부,120,112,104,86\n마케팅팀,45,44,42,38\n재무팀,30,26,14,9\n인사팀,25,14,12,10\n연구개발,80,71,66,38\n고객지원,60,58,52,47\n\n주차,영업본부,마케팅팀,재무팀,인사팀,연구개발,고객지원\n1주,22,30,8,10,18,25\n2주,38,51,12,16,26,41\n3주,49,64,17,22,33,55\n4주,58,72,22,28,38,63\n5주,64,79,25,33,42,70\n6주,68,82,27,36,45,76\n7주,70,84,29,38,47,77\n8주,72,84,30,40,48,78`;\nconst STAGES = ['라이선스', '교육 이수', '첫 사용', '주간 활성'];\nconst RX = [\n  ['교육 이수', '교육 전 단계에서 빠져요', '팀장을 통해 교육 일정을 다시 안내하고, 30분 온라인 · 녹화 교육으로 바꿔 참석 부담을 줄이세요. 이수하지 않은 사람 목록을 챔피언에게 전달하세요.'],\n  ['첫 사용', '교육은 들었지만 써 보지 않아요', '교육 직후 \"첫 과제\"(내 메일 요약해 보기 등)를 주고, 부서 업무에 맞는 복사용 프롬프트 3개를 배포하세요. 쓸 일이 떠오르지 않는 게 가장 흔한 원인이에요.'],\n  ['주간 활성', '한두 번 쓰고 멈춰요', '\"매일 한 번 쓰기\" 2주 미션과 팀 회의 팁 공유를 시작하세요. 부서 업무에 맞는 시나리오가 없다면 시나리오 워크숍을 다시 여세요.']\n];\nconst COLORS = ['#0a6cbd', '#1a8f63', '#cf3f3f', '#d98a06', '#7b5cd6', '#0e9aa7', '#8a6d3b', '#e0559a'];\nconst $ = id => document.getElementById(id);\nconst esc = s => String(s).replace(/[&<>\"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' }[c]));\nlet depts = [], weeks = null, pick = '전체';\n\nfunction parse(t) {\n  const [a, b] = t.trim().split(/\\r?\\n\\s*\\r?\\n/);\n  const rows = a.trim().split(/\\r?\\n/).slice(1).map(l => l.split(/[,\\t]/).map(s => s.trim())).filter(c => c[0]);\n  depts = rows.map(c => ({ n: c[0], v: c.slice(1, 5).map(Number) }));\n  if (b) { const L = b.trim().split(/\\r?\\n/).map(l => l.split(/[,\\t]/).map(s => s.trim())); weeks = { names: L[0].slice(1), rows: L.slice(1).map(c => ({ w: c[0], v: c.slice(1).map(Number) })) }; } else { weeks = null; }\n}\nconst neckOf = v => { let w = 1, low = 2; for (let i = 1; i < 4; i++) { const r = v[i] / (v[i - 1] || 1); if (r < low) { low = r; w = i; } } return w; };\n\nfunction funnel() {\n  const v = pick === '전체' ? [0, 1, 2, 3].map(i => depts.reduce((s, d) => s + d.v[i], 0)) : depts.find(d => d.n === pick).v;\n  const neck = neckOf(v);\n  $('fsub').textContent = `${pick} · 최종 활성 ${Math.round(v[3] / v[0] * 100)}%`;\n  const cols = ['var(--f1)', 'var(--f2)', 'var(--f3)', 'var(--f4)'];\n  $('funnel').innerHTML = v.map((n, i) => (i ? `<div class=\"conv ${i === neck ? 'neck' : ''}\">↓ <b>${Math.round(n / v[i - 1] * 100)}%</b> 넘어감 · ${v[i - 1] - n}명 빠짐 ${i === neck ? '<span class=\"neckTag\">병목</span>' : ''}</div>` : '') +\n    `<div class=\"fs\" style=\"width:30%;background:${cols[i]}\" data-w=\"${Math.max(36, n / v[0] * 100)}\"><span>${STAGES[i]}<small>${Math.round(n / v[0] * 100)}%</small></span><span class=\"n\">${n.toLocaleString('ko-KR')}명</span></div>`).join('');\n  requestAnimationFrame(() => requestAnimationFrame(() => document.querySelectorAll('.fs').forEach(f => { f.style.width = f.dataset.w + '%'; })));\n  const byNeck = [1, 2, 3].map(i => depts.filter(d => neckOf(d.v) === i).map(d => d.n));\n  $('acts').innerHTML = RX.map((r, i) => `<li><div><b>${r[0]}</b><div class=\"hint\">${r[1]}</div></div><div>${byNeck[i].length ? `<div class=\"hint\" style=\"margin-bottom:4px\">해당 부서: <b>${byNeck[i].map(esc).join(', ')}</b></div>` : '<div class=\"hint\" style=\"margin-bottom:4px\">해당 부서 없음</div>'}${r[2]}</div></li>`).join('');\n}\n\nfunction table() {\n  const heat = r => r >= 0.9 ? 'rgba(26,143,99,.18)' : r >= 0.75 ? 'rgba(10,108,189,.14)' : r >= 0.6 ? 'rgba(217,138,6,.2)' : 'rgba(207,63,63,.22)';\n  $('tbl').innerHTML = '<tr><th>부서</th><th>라이선스</th><th>→ 교육 이수</th><th>→ 첫 사용</th><th>→ 주간 활성</th><th>최종 활성률</th></tr>' +\n    depts.map(d => { const nk = neckOf(d.v); return `<tr><td>${esc(d.n)}</td><td>${d.v[0]}</td>` + [1, 2, 3].map(i => { const r = d.v[i] / (d.v[i - 1] || 1); return `<td class=\"h\" style=\"background:${heat(r)};${i === nk ? 'outline:2px solid var(--bad);outline-offset:-2px' : ''}\">${Math.round(r * 100)}%</td>`; }).join('') + `<td class=\"h\">${Math.round(d.v[3] / d.v[0] * 100)}%</td></tr>`; }).join('');\n}\n\nfunction trend() {\n  if (!weeks) { $('trend').innerHTML = ''; return; }\n  const W = 900, H = 260, l = 40, r = 120, t = 12, b = 28, n = weeks.rows.length;\n  const x = i => l + (W - l - r) * i / Math.max(1, n - 1), y = v => H - b - (H - b - t) * v / 100;\n  let s = '';\n  [0, 25, 50, 75, 100].forEach(v => { s += `<line x1=\"${l}\" x2=\"${W - r}\" y1=\"${y(v)}\" y2=\"${y(v)}\" stroke=\"var(--line)\"/><text x=\"${l - 6}\" y=\"${y(v) + 4}\" text-anchor=\"end\">${v}%</text>`; });\n  weeks.rows.forEach((rw, i) => { s += `<text x=\"${x(i)}\" y=\"${H - 8}\" text-anchor=\"middle\">${esc(rw.w)}</text>`; });\n  weeks.names.forEach((nm, k) => {\n    const c = COLORS[k % COLORS.length], dim = pick !== '전체' && pick !== nm;\n    const pts = weeks.rows.map((rw, i) => `${x(i)},${y(rw.v[k])}`).join(' ');\n    const last = weeks.rows[n - 1].v[k];\n    s += `<polyline points=\"${pts}\" fill=\"none\" stroke=\"${c}\" stroke-width=\"${dim ? 1.5 : 3}\" opacity=\"${dim ? .25 : 1}\" stroke-linejoin=\"round\"/>`;\n    s += `<text x=\"${x(n - 1) + 8}\" y=\"${y(last) + 4}\" style=\"fill:${c};font-weight:700;opacity:${dim ? .35 : 1}\">${esc(nm)} ${last}%</text>`;\n  });\n  $('trend').innerHTML = s;\n  $('tleg').innerHTML = '<span class=\"hint\">위 부서 버튼을 누르면 그 부서만 강조돼요.</span>';\n}\n\nfunction draw() {\n  $('sel').innerHTML = ['전체', ...depts.map(d => d.n)].map(n => `<button class=\"${n === pick ? 'on' : ''}\">${esc(n)}</button>`).join('');\n  $('sel').querySelectorAll('button').forEach(b => b.onclick = () => { pick = b.textContent; draw(); });\n  funnel(); table(); trend();\n}\nfunction run() { parse($('src').value); if (!depts.some(d => d.n === pick)) { pick = '전체'; } draw(); }\n$('src').value = SAMPLE;\n$('run').onclick = run;\n$('sample').onclick = () => { $('src').value = SAMPLE; run(); };\nrun();\n</script>\n</body>\n</html>\n"}],"agents":[{"Title":"DEMO-AG-POLICY","AgentName":"사내 규정 도우미","Summary":"휴가 · 출장 · 경비 규정을 근거 조항과 함께 바로 답해요","BuildTool":"Agent Builder","TaskArea":["프로젝트·사내 업무 하기"],"Output":["답변"],"OutputNote":"근거 규정 이름과 조항이 붙은 짧은 답변","Scope":["사내 업무용"],"Does":["휴가 · 출장 · 경비 · 보안 규정 질문에 바로 답해요","답변 끝에 근거 문서와 조항을 붙여요","규정에 없는 내용은 담당 부서를 알려 줘요"],"Prompts":["해외 출장 일비는 얼마야?","반차를 쓰려면 언제까지 신청해야 해?","법인카드로 회식비 결제할 때 한도가 있어?"],"MakerNote":"경영지원팀에 오던 규정 질문이 매주 30건이 넘었어요. 이제 Agent가 먼저 답하고, 사람은 예외만 봐요.","Instructions":"너는 MUNI LABS 사내 규정 도우미야.\n- 연결된 규정 문서에 있는 내용만 근거로 답해.\n- 답변 끝에 [출처: 문서명 > 조항]을 붙여.\n- 문서에 없으면 추측하지 말고 담당 부서(경영지원팀)를 안내해.\n- 금액 · 기한은 원문 그대로 써.","Config":{"knowledge":[{"name":"사내 규정집","where":"SharePoint 경영지원 사이트 > 규정 문서함","type":"문서"},{"name":"경비 처리 FAQ","where":"SharePoint 페이지","type":"페이지"}],"tools":[]},"rel":[["1.0","처음 배포",52],["1.1","출처 표시 규칙 추가",21],["1.2","보안 규정 문서 연결",6]],"skills":[]},{"Title":"DEMO-AG-BRIEFING","AgentName":"고객 미팅 브리핑","Summary":"미팅 전 고객과 주고받은 메일 · 문서 · 지난 회의를 한 장으로","BuildTool":"Copilot Studio","TaskArea":["고객 업무 이해하고 설계하기"],"Output":["문서 초안","체크리스트"],"OutputNote":"고객 현황 · 지난 논의 · 오늘 논의 포인트 3개 · 예상 질문이 담긴 한 장 브리핑","Scope":["고객 프로젝트용"],"Does":["다음 미팅 고객과의 최근 메일 · Teams 회의 · 공유 문서를 모아요","지난 논의와 아직 안 끝난 일을 정리해요","오늘 꺼낼 논의 포인트와 예상 질문을 뽑아요"],"Prompts":["내일 오전 A사 미팅 브리핑 만들어 줘","지난 3번의 회의에서 고객이 걱정한 것만 정리해 줘","오늘 미팅에서 받을 만한 질문 5개와 답 초안"],"MakerNote":"미팅 전에 메일함 · Teams · SharePoint를 뒤지던 30분이 3분이 됐어요. 대표님 미팅 전에 특히 많이 써요.","Instructions":"너는 컨설턴트의 고객 미팅 준비를 돕는 브리핑 작성자야.\n- 사용자 일정에서 다음 고객 미팅을 찾고, 그 고객과 관련된 최근 메일 · 회의 · 문서만 근거로 써.\n- 형식: 고객 현황 / 지난 논의 / 미결 사항 / 오늘 논의 포인트 3개 / 예상 질문과 답.\n- 한 페이지를 넘기지 마.","Config":{"knowledge":[{"name":"고객 프로젝트 사이트","where":"SharePoint 프로젝트 사이트","type":"사이트"}],"tools":[{"name":"일정 읽기","connector":"Office 365 Outlook","kind":"작업"},{"name":"메일 검색","connector":"Office 365 Outlook","kind":"작업"}]},"rel":[["1.0","처음 배포",33],["1.1","예상 질문과 답 추가",8]],"skills":["고객 인터뷰 → 현황 진단"]},{"Title":"DEMO-AG-WEEKLY","AgentName":"프로젝트 주간 보고 작성기","Summary":"한 주의 회의록 · 메일 · Planner를 모아 고객 주간 보고 초안으로","BuildTool":"Copilot Studio","TaskArea":["프로젝트·사내 업무 하기"],"Output":["문서 초안","표"],"OutputNote":"진행 현황 · 이번 주 한 일 · 다음 주 계획 · 이슈와 위험이 담긴 주간 보고 Word 초안","Scope":["고객 프로젝트용"],"Does":["이번 주 프로젝트 회의록 · 메일 · Planner 작업을 모아요","한 일 · 다음 주 계획 · 이슈를 표로 나눠요","고객 보고 양식에 맞춘 Word 초안을 만들어요"],"Prompts":["B사 프로젝트 이번 주 주간 보고 만들어 줘","이슈와 위험만 표로 다시 정리해 줘","고객용으로 말투를 정중하게 바꿔 줘"],"MakerNote":"금요일마다 PM들이 1시간씩 쓰던 주간 보고를 10분 검토로 줄였어요.","Instructions":"너는 컨설팅 프로젝트 PM의 주간 보고 작성자야.\n- 이번 주(월~금) 자료만 근거로 써.\n- 진행률은 Planner 완료 비율로 계산해.\n- 이슈는 영향 · 대응 · 담당 · 기한으로 나눠.\n- 고객에게 보낼 정중한 존댓말로 써.","Config":{"knowledge":[{"name":"프로젝트 회의록","where":"SharePoint 프로젝트 사이트 > 회의록","type":"문서"},{"name":"주간 보고 양식","where":"SharePoint 템플릿 문서함","type":"문서"}],"tools":[{"name":"Planner 작업 읽기","connector":"Planner","kind":"작업"},{"name":"Word 문서 만들기","connector":"Word Online","kind":"작업"}]},"rel":[["1.0","처음 배포",45],["1.1","Planner 진행률 계산 추가",15],["2.0","Word 초안 자동 생성",3]],"skills":["프로젝트 착수 패키지"]},{"Title":"DEMO-AG-SME","AgentName":"사내 전문가 찾기","Summary":"\"이 주제 누가 잘 알아?\"에 프로젝트 이력으로 사람을 찾아 줘요","BuildTool":"Agent Builder","TaskArea":["프로젝트·사내 업무 하기"],"Output":["답변","표"],"OutputNote":"전문가 이름 · 관련 프로젝트 · 근거 문서가 담긴 추천 표","Scope":["사내 업무용"],"Does":["주제를 말하면 관련 프로젝트를 한 사람을 찾아요","추천 이유(프로젝트, 문서, 사례)를 같이 보여 줘요","Teams 채팅으로 바로 물어볼 수 있게 이름을 알려 줘요"],"Prompts":["Copilot Studio 커넥터 경험 있는 사람 찾아 줘","금융권 Copilot 도입 프로젝트 해 본 사람은?","민감도 레이블 설계 잘 아는 사람 3명 추천해 줘"],"MakerNote":"신규 프로젝트 제안 때 \"이거 해 본 사람?\"을 Teams에 묻고 반나절 기다리던 걸 없앴어요.","Instructions":"너는 MUNI LABS의 사내 전문가 찾기 도우미야.\n- 프로젝트 사례 · 산출물 문서의 작성자와 참여자를 근거로 추천해.\n- 최대 3명, 각자 근거 프로젝트와 문서를 붙여.\n- 개인 평가나 순위를 매기지 마.","Config":{"knowledge":[{"name":"프로젝트 사례 목록","where":"SharePoint MUNIVERSE > Case Library","type":"목록"},{"name":"산출물 문서함","where":"SharePoint 프로젝트 아카이브","type":"문서"}],"tools":[]},"rel":[["1.0","처음 배포",24]],"skills":[]},{"Title":"DEMO-AG-PLANDAY","AgentName":"오늘의 업무 계획","Summary":"일정 · 메일 · 할 일을 보고 오늘 할 일의 순서를 짜 줘요","BuildTool":"Agent Builder","TaskArea":["프로젝트·사내 업무 하기"],"Output":["체크리스트"],"OutputNote":"시간대별 오늘 계획과 꼭 답해야 할 메일 목록","Scope":["사내 업무용"],"Does":["오늘 일정 사이의 빈 시간을 찾아요","답해야 할 메일과 마감이 가까운 할 일을 골라요","시간대별 오늘 계획을 체크리스트로 만들어요"],"Prompts":["오늘 계획 짜 줘","오후에 집중 시간 2시간 확보해 줘","오늘 꼭 답해야 할 메일만 알려 줘"],"MakerNote":"아침마다 Outlook · Teams · To Do를 오가며 10분씩 정리하던 걸 한 번에 해요.","Instructions":"너는 사용자의 하루 계획을 돕는 비서야.\n- 오늘 일정, 지난 24시간 받은 메일, To Do 할 일을 근거로 써.\n- 회의 사이 30분 이상 빈 시간에 할 일을 배치해.\n- 답장이 필요한 메일은 보낸 사람 · 제목 · 이유를 한 줄로.","Config":{"knowledge":[],"tools":[{"name":"일정 읽기","connector":"Office 365 Outlook","kind":"작업"},{"name":"할 일 읽기","connector":"Microsoft To Do","kind":"작업"}]},"rel":[["1.0","처음 배포",17],["1.1","집중 시간 확보 기능",5]],"skills":[]},{"Title":"DEMO-AG-LEARN","AgentName":"Copilot 학습 코치","Summary":"내 직무에 맞는 Copilot 활용법을 매일 하나씩 알려 줘요","BuildTool":"Copilot Studio","TaskArea":["교육·확산 프로그램 운영하기"],"Output":["답변","체크리스트"],"OutputNote":"직무 맞춤 활용 팁 · 바로 쓰는 프롬프트 · 오늘의 미션","Scope":["사내 업무용","고객 프로젝트용"],"Does":["직무와 업무를 말하면 Copilot 활용 장면을 추천해요","복사해 쓰는 프롬프트와 고친 예시를 보여 줘요","매일 하나씩 해 볼 미션을 줘요"],"Prompts":["나는 재무팀이야. Excel에서 Copilot 어떻게 써?","회의록 요약 프롬프트 더 좋게 고쳐 줘","오늘의 Copilot 미션 줘"],"MakerNote":"고객사 교육이 끝난 뒤에도 직원들이 계속 물어볼 곳이 필요해서 만들었어요. 고객사에 맞게 복사해서 배포해요.","Instructions":"너는 Microsoft 365 Copilot 학습 코치야.\n- 사용자의 직무를 먼저 묻고, 그 직무의 실제 업무 장면으로 설명해.\n- 프롬프트는 목표 · 맥락 · 자료 · 기대 결과 네 요소를 갖춰 완성된 문장으로.\n- 한 번에 팁은 3개까지만.","Config":{"knowledge":[{"name":"Copilot 활용 가이드","where":"SharePoint 교육 자료실","type":"문서"},{"name":"Microsoft Learn","where":"learn.microsoft.com","type":"웹사이트"}],"tools":[]},"rel":[["1.0","처음 배포",38],["1.1","오늘의 미션 추가",10]],"skills":["직무별 프롬프트 교육 자료","챔피언 프로그램 운영 가이드"]}]});
